:root {
  --void: #04060c;
  --void-2: #070d18;
  --ink: #e8f7ff;
  --muted: #8ea6b8;
  --dim: #5b7183;
  --cyan: #6ff7f0;
  --cyan-soft: rgba(111, 247, 240, 0.16);
  --cyan-line: rgba(111, 247, 240, 0.26);
  --red: #ff4f6d;
  --red-soft: rgba(255, 79, 109, 0.18);
  --amber: #ffc35c;
  --violet: #b38bff;
  --panel: linear-gradient(150deg, rgba(10, 20, 32, 0.82), rgba(5, 10, 18, 0.5));
  --font-display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Roboto Condensed", "Segoe UI", system-ui, sans-serif;
  --font-mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Liberation Mono", Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--void);
  color: var(--ink);
  font-family: var(--font-display);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#stage {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(140% 110% at 50% 30%, #0a1524 0%, #05080f 50%, #02040a 100%);
  isolation: isolate;
}

#arena {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

.is-hidden { display: none !important; }

.grain,
.vignette,
.slow-wash,
.damage-wash {
  position: absolute;
  inset: -2px;
  pointer-events: none;
  z-index: 40;
}

.grain {
  opacity: 0.28;
  background-image:
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.028) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.012) 0 1px, transparent 1px 4px);
  mix-blend-mode: soft-light;
}

.vignette {
  background:
    radial-gradient(ellipse 78% 72% at 50% 48%, transparent 38%, rgba(0, 2, 6, 0.42) 72%, rgba(0, 2, 6, 0.88) 100%),
    linear-gradient(180deg, rgba(0, 2, 6, 0.45), transparent 12%, transparent 86%, rgba(0, 2, 6, 0.55));
}

.slow-wash {
  opacity: 0;
  background:
    radial-gradient(circle at 50% 50%, transparent 30%, rgba(47, 111, 255, 0.16) 100%),
    linear-gradient(180deg, rgba(50, 140, 255, 0.06), rgba(20, 40, 120, 0.12));
  mix-blend-mode: screen;
  transition: opacity 120ms linear;
}

.slow-wash.on { opacity: 1; }

.damage-wash {
  opacity: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 42%, rgba(255, 32, 66, 0.55) 100%);
  transition: opacity 90ms linear;
}

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */

.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(300px, 460px) minmax(180px, 1fr);
  align-items: start;
  gap: clamp(10px, 1.6vw, 26px);
  padding:
    max(16px, env(safe-area-inset-top))
    max(20px, env(safe-area-inset-right))
    0
    max(20px, env(safe-area-inset-left));
  pointer-events: none;
}

.panel {
  position: relative;
  background: var(--panel);
  border: 1px solid rgba(111, 247, 240, 0.14);
  box-shadow:
    0 10px 40px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  padding: 10px 13px 9px;
  pointer-events: none;
}

.panel::before,
.panel::after {
  content: "";
  position: absolute;
  width: 9px;
  height: 9px;
  border: 1px solid rgba(111, 247, 240, 0.55);
  pointer-events: none;
}

.panel::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.panel::after { right: -1px; bottom: -1px; border-left: 0; border-top: 0; }

.panel-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 14px;
}

.eyebrow {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: var(--dim);
  text-transform: uppercase;
}

.dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  margin-right: 6px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  vertical-align: 1px;
}

.vitals { justify-self: start; width: min(230px, 100%); }

.hpnum { font-size: 13px; color: var(--cyan); letter-spacing: 0.06em; }
.hpnum.low { color: var(--red); }

.hp-track {
  position: relative;
  height: 9px;
  margin: 5px 0 8px;
  background: rgba(2, 8, 12, 0.85);
  border: 1px solid rgba(111, 247, 240, 0.15);
  overflow: hidden;
}

.hp-fill {
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #3bc8c2, var(--cyan) 65%, #d8fffb);
  box-shadow: 0 0 14px rgba(111, 247, 240, 0.55);
  transition: width 120ms linear, background 220ms linear;
}

.hp-fill.low {
  background: linear-gradient(90deg, #a21734, var(--red) 70%, #ffc4cc);
  box-shadow: 0 0 14px rgba(255, 79, 109, 0.6);
}

.hp-ticks {
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(3, 9, 14, 0.9) calc(10% - 1px) 10%);
}

.wave-line { display: flex; align-items: baseline; gap: 7px; }
.wavenum { font-size: 11px; color: var(--ink); letter-spacing: 0.08em; }
.wave-sub {
  margin-left: auto;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.future { justify-self: center; width: 100%; }

.debt-eyebrow { color: rgba(255, 120, 140, 0.8); }
.debt-label { font-size: 9px; color: var(--dim); letter-spacing: 0.1em; }
.debt-label.hot { color: var(--red); text-shadow: 0 0 10px rgba(255, 79, 109, 0.6); }

.timeline {
  position: relative;
  height: 29px;
  margin: 7px 0 5px;
}

.timeline-rail {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, rgba(255, 79, 109, 0.45), rgba(255, 79, 109, 0.12) 70%, rgba(255, 79, 109, 0.02));
}

.timeline-rail::after {
  content: "";
  position: absolute;
  inset: -3px 0;
  background-image: repeating-linear-gradient(90deg, rgba(255, 120, 140, 0.22) 0 1px, transparent 1px 10%);
}

.now-mark {
  position: absolute;
  left: -1px;
  top: 3px;
  bottom: 3px;
  width: 2px;
  background: var(--red);
  box-shadow: 0 0 12px rgba(255, 79, 109, 0.9);
}

.now-mark::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 50%;
  width: 5px;
  height: 5px;
  background: var(--red);
  transform: translateY(-50%) rotate(45deg);
  box-shadow: 0 0 8px var(--red);
}

.motes { position: absolute; inset: 0; }

.mote {
  position: absolute;
  top: 3px;
  width: 6px;
  height: 23px;
  margin-left: -3px;
  border-radius: 1px;
  background: linear-gradient(180deg, #ffd9a0, var(--red));
  box-shadow: 0 0 9px rgba(255, 79, 109, 0.75);
  will-change: left;
}

.mote::after {
  content: "";
  position: absolute;
  left: 2px;
  right: 2px;
  top: 3px;
  bottom: 3px;
  background: rgba(255, 240, 230, 0.7);
}

.mote.overdue {
  left: 0 !important;
  background: #fff;
  animation: moteHeld 0.55s steps(2, end) infinite;
}

@keyframes moteHeld {
  50% { opacity: 0.25; }
}

.future-edge {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  padding-left: 4px;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  color: rgba(255, 120, 140, 0.55);
  background: linear-gradient(90deg, transparent, rgba(10, 16, 26, 0.9) 40%);
}

.timeline-caption {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 8px;
  letter-spacing: 0.14em;
  color: var(--dim);
  white-space: nowrap;
  overflow: hidden;
}

.timeline-caption span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  color: rgba(255, 130, 150, 0.5);
}

.future.danger { border-color: rgba(255, 79, 109, 0.35); }
.future.danger .timeline-rail { background: linear-gradient(90deg, rgba(255, 79, 109, 0.8), rgba(255, 79, 109, 0.2)); }
.future.danger .timeline-rail::after { animation: railPulse 0.8s ease-in-out infinite; }

@keyframes railPulse {
  50% { opacity: 0.4; }
}

.run {
  justify-self: end;
  width: min(230px, 100%);
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    "score buttons"
    "sub buttons";
  column-gap: 10px;
  align-items: center;
}

.score-block { grid-area: score; display: flex; align-items: baseline; gap: 8px; }
.score { font-size: 20px; line-height: 1; letter-spacing: 0.02em; color: var(--ink); }

.run-sub { grid-area: sub; margin-top: 5px; }
.stolen { font-size: 8px; letter-spacing: 0.16em; color: var(--dim); }
.stolen b { font-size: 11px; color: var(--amber); font-weight: 400; margin-left: 3px; }
.stolen i { font-style: normal; color: var(--amber); }

.run-buttons {
  grid-area: buttons;
  display: flex;
  gap: 5px;
  pointer-events: auto;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  padding: 0;
  border: 1px solid rgba(111, 247, 240, 0.2);
  background: rgba(5, 12, 20, 0.65);
  color: var(--muted);
  font: 10px/1 var(--font-mono);
  cursor: pointer;
  transition: color 140ms, border-color 140ms, background 140ms;
}

.icon-btn:hover { color: var(--cyan); border-color: var(--cyan); background: rgba(111, 247, 240, 0.08); }
.icon-btn:focus-visible { outline: 1px solid var(--cyan); outline-offset: 2px; }
.icon-btn.muted { color: var(--red); }
.audio-glyph { font-size: 12px; }

/* ------------------------------------------------------------------ */
/* Boss bar, banner, combo, toasts, hints                              */
/* ------------------------------------------------------------------ */

.bossbar {
  position: absolute;
  z-index: 19;
  top: max(112px, calc(env(safe-area-inset-top) + 94px));
  left: 50%;
  width: min(540px, 66vw);
  transform: translateX(-50%);
  padding: 8px 12px 7px;
  background: linear-gradient(180deg, rgba(20, 8, 22, 0.88), rgba(8, 5, 14, 0.62));
  border: 1px solid rgba(255, 79, 109, 0.3);
  box-shadow: 0 0 40px rgba(255, 40, 90, 0.12);
  pointer-events: none;
  animation: bossIn 420ms ease-out both;
}

@keyframes bossIn {
  from { opacity: 0; transform: translate(-50%, -8px); }
}

.boss-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px; }
.boss-head .eyebrow { color: rgba(255, 150, 165, 0.85); }
.boss-phase { font-size: 8px; letter-spacing: 0.12em; color: var(--red); }

.boss-track {
  position: relative;
  height: 6px;
  background: rgba(0, 0, 0, 0.65);
  border: 1px solid rgba(255, 79, 109, 0.2);
}

.boss-track i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #7f1430, var(--red) 70%, #ffb1be);
  box-shadow: 0 0 14px rgba(255, 79, 109, 0.6);
  transition: width 160ms linear;
}

.boss-sub {
  margin-top: 5px;
  font-size: 7px;
  letter-spacing: 0.26em;
  color: rgba(255, 150, 165, 0.4);
  text-align: right;
}

.banner {
  position: absolute;
  z-index: 22;
  top: 23%;
  left: 50%;
  transform: translate(-50%, 8px);
  text-align: center;
  pointer-events: none;
  opacity: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  width: 90vw;
}

.banner.show { animation: bannerShow 2.3s cubic-bezier(0.22, 0.8, 0.3, 1) both; }

@keyframes bannerShow {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.98); filter: blur(4px); }
  12% { opacity: 1; transform: translate(-50%, 0) scale(1); filter: blur(0); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -10px) scale(1.01); }
}

.banner-title {
  font-size: clamp(26px, 4vw, 52px);
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--ink);
  text-shadow: 0 0 28px rgba(111, 247, 240, 0.35), 0 2px 24px rgba(0, 0, 0, 0.8);
  line-height: 1;
}

.banner-sub {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.34em;
  color: var(--red);
  text-shadow: 0 0 14px rgba(255, 79, 109, 0.6);
}

.combo {
  position: absolute;
  z-index: 21;
  right: max(28px, 5vw);
  top: 44%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  color: var(--amber);
  opacity: 0;
  transform: translateX(10px) skewX(-6deg);
  transition: opacity 160ms, transform 160ms;
  pointer-events: none;
  text-shadow: 0 0 20px rgba(255, 195, 92, 0.5);
}

.combo.show { opacity: 1; transform: translateX(0) skewX(-6deg); }
.combo span { font-size: 30px; line-height: 1; letter-spacing: -0.04em; }
.combo small { font-size: 7px; letter-spacing: 0.32em; color: rgba(255, 195, 92, 0.65); margin-top: 3px; }

.toasts {
  position: absolute;
  z-index: 23;
  left: 50%;
  bottom: 92px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  width: min(560px, 86vw);
}

.toast {
  padding: 7px 14px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink);
  background: rgba(4, 10, 16, 0.78);
  border: 1px solid rgba(111, 247, 240, 0.22);
  border-left: 2px solid var(--cyan);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
  animation: toastIn 260ms ease-out both;
  text-align: center;
}

.toast.warn { border-left-color: var(--red); color: #ffd6dc; border-color: rgba(255, 79, 109, 0.25); }
.toast.gold { border-left-color: var(--amber); color: #ffe9bd; border-color: rgba(255, 195, 92, 0.25); }
.toast.out { animation: toastOut 320ms ease-in both; }

@keyframes toastIn {
  from { opacity: 0; transform: translateY(8px); }
}

@keyframes toastOut {
  to { opacity: 0; transform: translateY(-6px); }
}

.hint {
  position: absolute;
  z-index: 21;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: flex;
  gap: 14px;
  font-size: 8px;
  letter-spacing: 0.14em;
  color: rgba(142, 166, 184, 0.55);
  pointer-events: none;
  transition: opacity 700ms;
}

.hint kbd { margin-right: 2px; }
.hint.faded { opacity: 0; }

kbd {
  display: inline-block;
  padding: 1px 4px;
  border: 1px solid rgba(111, 247, 240, 0.24);
  background: rgba(111, 247, 240, 0.06);
  color: rgba(200, 255, 250, 0.8);
  font: 8px/1.5 var(--font-mono);
  letter-spacing: 0.05em;
}

/* ------------------------------------------------------------------ */
/* Touch controls                                                      */
/* ------------------------------------------------------------------ */

.touch {
  position: absolute;
  inset: 0;
  z-index: 24;
  pointer-events: none;
}

.ability {
  position: absolute;
  width: 70px;
  height: 70px;
  border-radius: 50%;
  border: 1px solid rgba(111, 247, 240, 0.32);
  background:
    radial-gradient(circle at 50% 42%, rgba(111, 247, 240, 0.13), rgba(4, 10, 18, 0.66) 70%);
  color: var(--ink);
  font-family: var(--font-display);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  pointer-events: auto;
  touch-action: none;
  box-shadow: 0 0 24px rgba(0, 0, 0, 0.4), inset 0 0 22px rgba(111, 247, 240, 0.05);
  transition: border-color 100ms, background 100ms, transform 100ms;
}

.ability span { font-size: 10px; font-weight: 800; letter-spacing: 0.14em; }
.ability small { font-size: 6px; letter-spacing: 0.18em; color: var(--dim); }

.ability.slow {
  right: max(20px, env(safe-area-inset-right));
  bottom: calc(208px + env(safe-area-inset-bottom));
}

.ability.dash {
  left: max(20px, env(safe-area-inset-left));
  bottom: calc(208px + env(safe-area-inset-bottom));
}

.ability.slow.held {
  border-color: var(--amber);
  background: radial-gradient(circle at 50% 42%, rgba(255, 195, 92, 0.28), rgba(20, 8, 4, 0.7) 70%);
  box-shadow: 0 0 30px rgba(255, 195, 92, 0.28), inset 0 0 22px rgba(255, 195, 92, 0.12);
  transform: scale(0.96);
}

.ability.dash.cooling { opacity: 0.5; }
.ability.dash.cooling small { color: var(--red); }
.ability:active { transform: scale(0.94); }

/* ------------------------------------------------------------------ */
/* Overlays                                                            */
/* ------------------------------------------------------------------ */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 60;
  overflow: hidden;
}

.title-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse 70% 60% at 50% 45%, rgba(4, 8, 16, 0.22) 0%, rgba(3, 5, 10, 0.74) 58%, rgba(2, 4, 9, 0.96) 100%),
    linear-gradient(180deg, rgba(2, 5, 10, 0.55), rgba(2, 4, 9, 0.35));
  animation: screenIn 500ms ease-out both;
}

@keyframes screenIn {
  from { opacity: 0; }
}

.title-screen.fade-out {
  animation: screenOut 420ms ease-in both;
  pointer-events: none;
}

@keyframes screenOut {
  to { opacity: 0; }
}

.title-ghost {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0.68;
}

.ghost-clock {
  position: absolute;
  width: min(92vh, 92vw);
  aspect-ratio: 1;
  border: 1px solid rgba(111, 247, 240, 0.08);
  border-radius: 50%;
  background:
    conic-gradient(from 0deg, transparent 0 8%, rgba(111, 247, 240, 0.06) 8.5%, transparent 9% 25%, rgba(255, 79, 109, 0.05) 25.5%, transparent 26% 100%);
  animation: ghostSpin 90s linear infinite;
}

.ghost-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px dashed rgba(111, 247, 240, 0.07);
}

.ghost-ring.r1 { width: min(70vh, 70vw); aspect-ratio: 1; animation: ghostSpin 60s linear infinite reverse; }
.ghost-ring.r2 { width: min(48vh, 48vw); aspect-ratio: 1; border-style: solid; border-color: rgba(255, 79, 109, 0.07); }
.ghost-ring.r3 { width: min(30vh, 30vw); aspect-ratio: 1; border-color: rgba(111, 247, 240, 0.06); animation: ghostSpin 30s linear infinite; }

@keyframes ghostSpin {
  to { transform: rotate(360deg); }
}

.title-inner {
  position: relative;
  z-index: 2;
  width: min(1040px, 92vw);
  padding: 3vh 0 4vh;
  text-align: center;
}

.kicker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin: 0 0 12px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
  color: rgba(142, 166, 184, 0.7);
}

.kicker-line { width: clamp(20px, 5vw, 72px); height: 1px; background: linear-gradient(90deg, transparent, rgba(111, 247, 240, 0.55), transparent); }

.logo {
  margin: 0;
  font-size: clamp(66px, 10.5vw, 148px);
  line-height: 0.8;
  font-weight: 900;
  letter-spacing: -0.015em;
  text-transform: uppercase;
}

.logo-borrowed {
  display: block;
  color: rgba(232, 247, 255, 0.06);
  -webkit-text-stroke: 1px rgba(200, 245, 250, 0.5);
  text-shadow: 0 0 38px rgba(111, 247, 240, 0.12);
  transform: translateX(-0.03em);
}

.logo-seconds {
  position: relative;
  display: block;
  color: var(--cyan);
  letter-spacing: 0.035em;
  text-shadow:
    0 0 12px rgba(111, 247, 240, 0.55),
    0 0 50px rgba(60, 230, 230, 0.28),
    0 8px 40px rgba(0, 0, 0, 0.75);
  background: linear-gradient(180deg, #f3fffe 8%, #9cfffa 38%, #42d8d1 78%, #1d8f94 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 18px rgba(111, 247, 240, 0.22));
}

.logo-seconds::before,
.logo-seconds::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  z-index: -1;
  -webkit-text-fill-color: currentColor;
  opacity: 0.32;
  pointer-events: none;
}

.logo-seconds::before { color: var(--red); transform: translate(2px, 0); clip-path: inset(20% 0 48% 0); animation: glitchA 7s steps(1, end) infinite; }
.logo-seconds::after { color: #55c6ff; transform: translate(-2px, 0); clip-path: inset(58% 0 22% 0); animation: glitchB 8s steps(1, end) infinite; }

@keyframes glitchA {
  0%, 93%, 100% { opacity: 0.18; transform: translate(2px, 0); }
  94% { opacity: 0.55; transform: translate(7px, -1px); }
  95% { opacity: 0.1; transform: translate(-4px, 1px); }
  96% { opacity: 0.5; transform: translate(2px, 0); }
}

@keyframes glitchB {
  0%, 90%, 100% { opacity: 0.16; transform: translate(-2px, 0); }
  91% { opacity: 0.5; transform: translate(-7px, 1px); }
  92% { opacity: 0.12; transform: translate(3px, -1px); }
  93% { opacity: 0.4; transform: translate(-2px, 0); }
}

.tagline {
  margin: 20px auto 0;
  max-width: 620px;
  font-size: clamp(12px, 1.35vw, 16px);
  font-weight: 500;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(220, 240, 248, 0.7);
}

.tagline::before,
.tagline::after { content: "—"; margin: 0 10px; color: rgba(255, 79, 109, 0.55); }

.mechanics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(12px, 2.4vw, 34px);
  width: min(900px, 100%);
  margin: clamp(26px, 4.5vh, 46px) auto 0;
  text-align: left;
}

.mech {
  display: flex;
  gap: 12px;
  padding-top: 11px;
  border-top: 1px solid rgba(111, 247, 240, 0.16);
  position: relative;
}

.mech::after {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 26px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
}

.mech-num {
  font-family: var(--font-mono);
  font-size: 9px;
  color: rgba(111, 247, 240, 0.45);
  padding-top: 2px;
}

.mech h2 {
  margin: 0 0 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: rgba(230, 252, 250, 0.9);
}

.mech p {
  margin: 0;
  font-size: 11px;
  line-height: 1.55;
  letter-spacing: 0.015em;
  color: rgba(142, 166, 184, 0.72);
}

.mech kbd { font-size: 8px; }

.title-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-top: clamp(26px, 4.2vh, 44px);
}

.play-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  width: 210px;
  height: 62px;
  padding: 0;
  border: 0;
  background: linear-gradient(100deg, #b7fffa, var(--cyan) 45%, #31c8c1);
  color: #03201f;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  cursor: pointer;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  box-shadow: 0 0 38px rgba(111, 247, 240, 0.32), 0 12px 40px rgba(0, 0, 0, 0.5);
  transition: transform 160ms, filter 160ms, box-shadow 160ms;
  overflow: hidden;
}

.play-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, rgba(255, 255, 255, 0.6) 48%, transparent 62%);
  transform: translateX(-120%);
  transition: transform 650ms ease;
}

.play-btn:hover { transform: translateY(-2px); filter: brightness(1.08); box-shadow: 0 0 56px rgba(111, 247, 240, 0.45), 0 16px 50px rgba(0, 0, 0, 0.55); }
.play-btn:hover::after { transform: translateX(120%); }
.play-btn:active { transform: translateY(0) scale(0.985); }
.play-btn:focus-visible { outline: 1px solid #fff; outline-offset: 5px; }
.play-btn span { margin-left: 0.34em; }
.play-btn i { font-style: normal; font-size: 18px; transform: translateY(-1px); }

.best-line {
  margin: 0;
  min-width: 92px;
  text-align: left;
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--dim);
}

.best-line b { display: block; margin-top: 4px; font-size: 15px; color: rgba(255, 195, 92, 0.9); font-weight: 400; letter-spacing: 0.06em; }

.title-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  width: min(900px, 100%);
  margin: clamp(24px, 4vh, 42px) auto 0;
  padding-top: 10px;
  border-top: 1px solid rgba(111, 247, 240, 0.09);
  font-size: 8px;
  letter-spacing: 0.17em;
  color: rgba(91, 113, 131, 0.9);
}

.title-version { color: rgba(255, 79, 109, 0.5); letter-spacing: 0.22em; }
.touch-only { display: none; }

/* ------------------------------------------------------------------ */
/* Modals                                                              */
/* ------------------------------------------------------------------ */

.modal-layer {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(2, 4, 9, 0.68);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  animation: screenIn 250ms ease-out both;
  padding: 20px;
}

.modal {
  position: relative;
  width: min(540px, 100%);
  padding: clamp(26px, 4vw, 42px);
  text-align: center;
  background:
    linear-gradient(160deg, rgba(12, 24, 36, 0.96), rgba(5, 9, 16, 0.94));
  border: 1px solid rgba(111, 247, 240, 0.18);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  animation: modalIn 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
}

.modal::before,
.modal::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  border: 1px solid rgba(111, 247, 240, 0.5);
}

.modal::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.modal::after { right: -1px; bottom: -1px; border-left: 0; border-top: 0; }

@keyframes modalIn {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
}

.modal-kicker {
  margin: 0 0 12px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.36em;
  color: rgba(255, 79, 109, 0.7);
}

.modal-title {
  margin: 0;
  font-size: clamp(34px, 5vw, 56px);
  line-height: 0.92;
  font-weight: 900;
  letter-spacing: 0.05em;
  color: var(--ink);
  text-shadow: 0 0 40px rgba(255, 79, 109, 0.22);
}

.modal-copy {
  margin: 18px auto 0;
  max-width: 380px;
  font-size: 11px;
  line-height: 1.7;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 26px;
}

.btn {
  min-width: 130px;
  height: 40px;
  padding: 0 18px;
  border: 1px solid rgba(111, 247, 240, 0.28);
  background: rgba(111, 247, 240, 0.08);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 140ms, border-color 140ms, color 140ms, transform 140ms;
}

.btn:hover { border-color: var(--cyan); background: rgba(111, 247, 240, 0.16); transform: translateY(-1px); }
.btn:focus-visible { outline: 1px solid var(--cyan); outline-offset: 3px; }
.btn.primary { background: var(--cyan); color: #03201f; border-color: var(--cyan); box-shadow: 0 0 28px rgba(111, 247, 240, 0.24); }
.btn.primary:hover { background: #b8fffb; }
.btn.ghost { background: rgba(5, 12, 20, 0.4); color: var(--muted); border-color: rgba(142, 166, 184, 0.18); }
.btn.ghost:hover { color: var(--ink); }

.modal-foot {
  margin: 18px 0 0;
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--dim);
}
.modal-foot kbd { font-size: 7px; }

.endcard { width: min(600px, 100%); }
.end-title { color: var(--red); text-shadow: 0 0 44px rgba(255, 79, 109, 0.28); }

.endcard.win .modal-kicker { color: rgba(111, 247, 240, 0.8); }
.endcard.win .end-title { color: var(--cyan); text-shadow: 0 0 44px rgba(111, 247, 240, 0.3); }
.endcard.win .modal::after { border-color: var(--cyan); }

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 24px 0 0;
  background: rgba(111, 247, 240, 0.1);
  border: 1px solid rgba(111, 247, 240, 0.1);
}

.stats > div {
  background: rgba(4, 9, 16, 0.86);
  padding: 11px 8px 9px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.stats b { font-size: 15px; font-weight: 400; color: var(--ink); letter-spacing: 0.02em; }
.stats > div:nth-child(2) b,
.stats > div:nth-child(3) b { color: var(--amber); }
.stats > div:nth-child(5) b { color: var(--cyan); }

.new-best {
  margin: 14px 0 0;
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--amber);
  animation: bestPulse 1.6s ease-in-out infinite;
}

@keyframes bestPulse {
  50% { opacity: 0.5; }
}

.noscript {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 30px;
  text-align: center;
  background: var(--void);
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 820px) {
  .hud {
    display: block;
    padding:
      max(10px, env(safe-area-inset-top))
      max(10px, env(safe-area-inset-right))
      0
      max(10px, env(safe-area-inset-left));
  }

  .panel { padding: 7px 9px 6px; }

  .vitals {
    position: absolute;
    top: max(10px, env(safe-area-inset-top));
    left: max(10px, env(safe-area-inset-left));
    width: calc(56% - 16px);
    max-width: 250px;
  }

  .run {
    position: absolute;
    top: max(10px, env(safe-area-inset-top));
    right: max(10px, env(safe-area-inset-right));
    width: calc(44% - 14px);
    max-width: 200px;
  }

  .score { font-size: 16px; }
  .eyebrow { font-size: 8px; letter-spacing: 0.18em; }
  .wave-sub { font-size: 7px; letter-spacing: 0.1em; }
  .hp-track { height: 7px; margin: 3px 0 5px; }
  .run-buttons { gap: 3px; }
  .icon-btn { width: 23px; height: 23px; font-size: 9px; }
  .audio-glyph { font-size: 10px; }

  .future {
    position: absolute;
    top: calc(max(10px, env(safe-area-inset-top)) + 66px);
    left: max(10px, env(safe-area-inset-left));
    right: max(10px, env(safe-area-inset-right));
    width: auto;
    max-width: none;
  }

  .timeline { height: 24px; margin: 5px 0 4px; }
  .mote { height: 18px; width: 5px; margin-left: -2.5px; top: 3px; }
  .timeline-caption { font-size: 7px; letter-spacing: 0.08em; }
  .future-edge { font-size: 7px; }
  .debt-label { font-size: 8px; }

  .bossbar {
    top: calc(max(10px, env(safe-area-inset-top)) + 138px);
    width: calc(100% - 28px);
  }
  .boss-sub { display: none; }

  .banner { top: 19%; }
  .banner-title { font-size: clamp(22px, 7vw, 34px); letter-spacing: 0.14em; }
  .banner-sub { font-size: 7px; letter-spacing: 0.24em; }

  .combo { right: 14px; top: 40%; }
  .combo span { font-size: 22px; }

  .toasts { bottom: 292px; width: calc(100% - 30px); gap: 5px; }
  .toast { font-size: 8px; padding: 6px 10px; letter-spacing: 0.12em; }

  .hint { display: none; }

  .title-inner { width: min(94vw, 560px); padding: 18px 0 max(18px, env(safe-area-inset-bottom)); max-height: 100%; overflow-y: auto; scrollbar-width: none; }
  .title-inner::-webkit-scrollbar { display: none; }

  .kicker { font-size: 7px; letter-spacing: 0.28em; gap: 8px; margin-bottom: 10px; }
  .logo { font-size: clamp(48px, 15vw, 80px); line-height: 0.82; }
  .tagline { font-size: 10px; letter-spacing: 0.08em; margin-top: 14px; }
  .tagline::before, .tagline::after { content: ""; margin: 0; }

  .mechanics {
    grid-template-columns: 1fr;
    gap: 0;
    margin-top: 18px;
    width: 100%;
  }

  .mech { padding: 8px 0; gap: 10px; align-items: flex-start; }
  .mech h2 { font-size: 9px; margin-bottom: 3px; letter-spacing: 0.22em; }
  .mech p { font-size: 10px; line-height: 1.45; }
  .mech-num { font-size: 8px; }
  .mech::after { width: 18px; }

  .title-actions { margin-top: 20px; gap: 14px; }
  .play-btn { width: 178px; height: 54px; font-size: 14px; letter-spacing: 0.28em; }
  .best-line { font-size: 7px; min-width: 66px; }
  .best-line b { font-size: 13px; }

  .title-foot { margin-top: 18px; font-size: 7px; letter-spacing: 0.1em; }
  .desktop-only { display: none; }
  .touch-only { display: inline; }

  .modal { padding: 26px 18px; }
  .modal-title { font-size: clamp(30px, 9vw, 44px); }
  .stats b { font-size: 13px; }
  .stats > div { padding: 9px 4px 7px; }
  .btn { min-width: 110px; height: 38px; font-size: 9px; padding: 0 12px; }
  .modal-actions { gap: 8px; }
}

@media (max-width: 420px) {
  .vitals { width: calc(57% - 14px); }
  .run { width: calc(43% - 12px); }
  .stats { grid-template-columns: repeat(3, 1fr); }
  .stats b { font-size: 12px; }
  .stats > div { padding: 8px 3px 6px; }
  .stats .eyebrow { font-size: 6.5px; letter-spacing: 0.12em; }
}

@media (max-height: 620px) and (orientation: landscape) {
  .title-inner { padding: 10px 0; max-height: 100%; overflow-y: auto; }
  .logo { font-size: clamp(40px, 11vh, 70px); }
  .mechanics { display: none; }
  .tagline { margin-top: 10px; }
  .title-actions { margin-top: 14px; }
  .title-foot { margin-top: 12px; }
  .ability.slow { bottom: calc(112px + env(safe-area-inset-bottom)); }
  .ability.dash { bottom: calc(112px + env(safe-area-inset-bottom)); }
  .toasts { bottom: 104px; }
}

@media (prefers-reduced-motion: reduce) {
  .ghost-clock, .ghost-ring, .logo-seconds::before, .logo-seconds::after, .new-best { animation: none; }
}

