input.content:
const WAVE_SUBTITLES = {
  1: "THE PRESENT",
  2: "THE PRESENT RESISTS",
  3: "INTEREST ACCRUES",
  4: "COLLECTION NOTICE",
  5: "THE AUDITOR",
};

const formatScore = (value) => Math.round(value).toLocaleString("en-US");

export class UI {
  constructor() {
    const byId = (id) => document.getElementById(id);
    this.el = {
      hud: byId("hud"),
      hpnum: byId("hpnum"),
      hpfill: byId("hpfill"),
      wavenum: byId("wavenum"),
      wavesub: byId("wavesub"),
      score: byId("score"),
      stolen: byId("stolen"),
      debtlabel: byId("debtlabel"),
      debtcaption: byId("debtcaption"),
      timeline: byId("timeline"),
      motes: byId("motes"),
      future: document.querySelector(".future"),
      combo: byId("combo"),
      combomult: byId("combomult"),
      bossbar: byId("bossbar"),
      bossfill: byId("bossfill"),
      bossphase: byId("bossphase"),
      hint: byId("hint"),
      touch: byId("touch"),
      btnSlow: byId("btn-slow"),
      btnDash: byId("btn-dash"),
      slowwash: byId("slowwash"),
      damagewash: byId("damagewash"),
      title: byId("title"),
      bestScore: byId("best-score"),
      pause: byId("pause"),
      gameover: byId("gameover"),
      endKicker: byId("end-kicker"),
      endTitle: byId("end-title"),
      endCopy: byId("end-copy"),
      statTime: byId("stat-time"),
      statWave: byId("stat-wave"),
      statDebt: byId("stat-debt"),
      statCollectors: byId("stat-collectors"),
      statScore: byId("stat-score"),
      statBest: byId("stat-best"),
      endBest: byId("end-best"),
      endcard: document.querySelector(".endcard"),
      audioBtn: byId("btn-audio"),
      pauseMute: byId("btn-pause-mute"),
      banner: byId("banner"),
      bannerTitle: byId("banner-title"),
      bannerSub: byId("banner-sub"),
      toasts: byId("toasts"),
    };

    this.moteEls = new Map();
    this.toastEls = [];
    this.last = Object.create(null);
    this.bannerTimer = 0;
    this.titleTimer = 0;
    this.touchMode = false;
    this.hintShownAt = 0;
    this.state = "title";
  }

  setText(key, value) {
    if (this.last[key] === value) return;
    this.last[key] = value;
    if (this.el[key]) this.el[key].textContent = value;
  }

  setTouchMode(enabled) {
    this.touchMode = enabled;
    document.body.classList.toggle("touch-mode", enabled);
  }

  setPlaying(playing) {
    this.state = playing ? "playing" : this.state;
    this.el.hud.classList.toggle("is-hidden", !playing);
    this.el.touch.classList.toggle("is-hidden", !(playing && this.touchMode));
    this.el.hint.classList.toggle("is-hidden", !(playing && !this.touchMode));
    if (playing) {
      this.hintShownAt = performance.now();
      this.el.hint.classList.remove("faded");
    }
  }

  hideHud() {
    this.el.hud.classList.add("is-hidden");
    this.el.touch.classList.add("is-hidden");
    this.el.hint.classList.add("is-hidden");
  }

  showTitle() {
    clearTimeout(this.titleTimer);
    this.el.title.classList.remove("is-hidden", "fade-out");
    this.state = "title";
    this.el.gameover.classList.add("is-hidden");
    this.el.pause.classList.add("is-hidden");
    this.hideHud();
    this.clearMotes();
    this.clearToasts();
    this.el.combo.classList.remove("show");
    this.el.bossbar.classList.add("is-hidden");
  }

  hideTitle() {
    if (this.el.title.classList.contains("is-hidden")) return;
    this.el.title.classList.add("fade-out");
    clearTimeout(this.titleTimer);
    this.titleTimer = setTimeout(() => {
      this.el.title.classList.add("is-hidden");
      this.el.title.classList.remove("fade-out");
    }, 430);
  }

  showPause() {
    this.el.pause.classList.remove("is-hidden");
  }

  hidePause() {
    this.el.pause.classList.add("is-hidden");
  }

  showEnd({ victory, stats, best, previousBest, touchMode }) {
    this.state = "end";
    this.hideHud();
    this.el.pause.classList.add("is-hidden");
    this.el.endcard.classList.toggle("win", victory);
    this.setText("endKicker", victory ? "AUDIT FAILED" : "DEBT COLLECTED");
    this.el.endKicker.textContent = victory ? "AUDIT FAILED" : "DEBT COLLECTED";
    this.el.endTitle.innerHTML = victory ? "DEBT<br />SETTLED" : "THE FUTURE<br />COLLECTED";
    this.el.endCopy.textContent = victory
      ? `The Auditor falls. You borrowed ${stats.borrowed.toFixed(1)} seconds and paid them back in full.`
      : `You borrowed ${stats.borrowed.toFixed(1)} seconds. The future took the rest.`;
    const seconds = Math.max(0, Math.floor(stats.time || 0));
    this.el.statTime.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
    this.el.statWave.textContent = String(stats.wave || 1).padStart(2, "0");
    this.el.statDebt.textContent = `${(stats.borrowed || 0).toFixed(1)}s`;
    this.el.statCollectors.textContent = String(stats.collectorsFaced || 0);
    this.el.statScore.textContent = formatScore(stats.score || 0);
    this.el.statBest.textContent = formatScore(best || 0);
    const isBest = (stats.score || 0) > (previousBest || 0);
    this.el.endBest.classList.toggle("is-hidden", !isBest);
    this.el.gameover.classList.remove("is-hidden");
    this.setTouchMode(touchMode);
    const focusTarget = document.getElementById("btn-again");
    setTimeout(() => focusTarget?.focus({ preventScroll: true }), 60);
  }

  hideEnd() {
    this.el.gameover.classList.add("is-hidden");
  }

  setBest(best) {
    this.el.bestScore.textContent = formatScore(best || 0);
  }

  setMuted(muted) {
    this.el.audioBtn.classList.toggle("muted", muted);
    this.el.audioBtn.querySelector(".audio-glyph").textContent = muted ? "◌" : "◉";
    this.el.audioBtn.setAttribute("aria-label", muted ? "Unmute audio" : "Mute audio");
    this.el.pauseMute.textContent = muted ? "Sound: Off" : "Sound: On";
  }

  update(game, paused = false) {
    if (this.el.hud.classList.contains("is-hidden")) {
      if (paused) return;
      return;
    }
    const hp = Math.max(0, game.player.hp);
    const hpPercent = Math.max(0, Math.min(100, (hp / game.player.maxHp) * 100));
    this.el.hpfill.style.width = `${hpPercent}%`;
    this.el.hpfill.classList.toggle("low", hp <= 30);
    this.el.hpnum.textContent = String(Math.ceil(hp));
    this.el.hpnum.classList.toggle("low", hp <= 30);

    this.setText("score", formatScore(game.score));
    this.setText("stolen", (game.stolen || 0).toFixed(1));
    this.setText("wavenum", String(game.wave).padStart(2, "0"));
    this.setText("wavesub", WAVE_SUBTITLES[game.wave] || "THE LOOP");

    const pending = game.debt.length;
    const activeCollectors = game.enemies.reduce(
      (total, enemy) => total + (enemy.type === "collector" && enemy.alive ? 1 : 0),
      0
    );
    const ready = game.debt.some((mote) => mote.fuse <= 0);
    const hot = pending > 0 || activeCollectors > 0;
    this.el.future.classList.toggle("damage", false);
    this.el.future.classList.toggle("danger", pending >= 3 || activeCollectors > 0);
    this.el.debtlabel.classList.toggle("hot", hot);
    this.setText("debtlabel", pending > 0 ? `${pending} PENDING` : "CLEAR");

    if (ready) this.setText("debtcaption", "COLLECTION OVERDUE · THE FUTURE IS QUEUED");
    else if (pending > 0) {
      const next = Math.min(...game.debt.map((mote) => mote.fuse));
      this.setText("debtcaption", `NEXT COLLECTION IN ${next.toFixed(1)}s`);
    } else if (activeCollectors > 0) {
      this.setText("debtcaption", `${activeCollectors} COLLECTOR${activeCollectors === 1 ? "" : "S"} IN THE ARENA`);
    } else {
      this.setText("debtcaption", "EVERY SECOND YOU STEAL ARRIVES HERE");
    }

    this.syncMotes(game.debt);

    if (game.combo >= 2) {
      this.el.combo.classList.add("show");
      this.setText("combomult", `×${game.comboMultiplier.toFixed(1)}`);
    } else {
      this.el.combo.classList.remove("show");
    }

    if (game.boss && !game.boss.dead) {
      this.el.bossbar.classList.remove("is-hidden");
      const ratio = Math.max(0, game.boss.hp / game.boss.maxHp);
      this.el.bossfill.style.width = `${ratio * 100}%`;
      this.setText("bossphase", game.boss.phase === 2 ? "PHASE II" : "PHASE I");
    } else {
      this.el.bossbar.classList.add("is-hidden");
    }

    this.el.slowwash.classList.toggle("on", game.timeScale < 0.72);
    const damageAlpha = Math.min(0.9, game.flash * 0.9);
    this.el.damagewash.style.opacity = String(damageAlpha);
    this.el.touch.classList.toggle("is-hidden", !(this.touchMode && !paused));

    if (this.touchMode) {
      this.el.btnSlow.classList.toggle("held", Boolean(game.input.slow) && game.status === "playing" && !paused);
      const cooldown = game.player.dashCd;
      this.el.btnDash.classList.toggle("cooling", cooldown > 0);
      const small = this.el.btnDash.querySelector("small");
      small.textContent = cooldown > 0 ? `${cooldown.toFixed(1)}s` : "READY";
    }

    if (this.el.hint.classList.contains("is-hidden") === false) {
      const age = performance.now() - this.hintShownAt;
      if (age > 12000) this.el.hint.classList.add("faded");
    }
  }

  syncMotes(debts) {
    const seen = new Set();
    for (const mote of debts) {
      seen.add(mote.id);
      let element = this.moteEls.get(mote.id);
      if (!element) {
        element = document.createElement("i");
        element.className = "mote";
        element.style.left = "100%";
        this.el.motes.appendChild(element);
        this.moteEls.set(mote.id, element);
      }
      const ratio = Math.max(0, Math.min(1, mote.fuse / 9));
      element.style.left = `${(1 - ratio) * 100}%`;
      element.classList.toggle("overdue", mote.fuse <= 0);
    }
    for (const [id, element] of this.moteEls) {
      if (!seen.has(id)) {
        element.remove();
        this.moteEls.delete(id);
      }
    }
  }

  clearMotes() {
    for (const element of this.moteEls.values()) element.remove();
    this.moteEls.clear();
    this.el.motes.innerHTML = "";
  }

  banner(title, sub) {
    this.el.bannerTitle.textContent = title;
    this.el.bannerSub.textContent = sub || "";
    this.el.banner.classList.remove("show");
    void this.el.banner.offsetWidth;
    this.el.banner.classList.add("show");
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => {
      this.el.banner.classList.remove("show");
    }, 2400);
  }

  toast(text, tone = "") {
    if (!text) return;
    const element = document.createElement("div");
    element.className = `toast ${tone}`.trim();
    element.textContent = text;
    this.el.toasts.appendChild(element);
    this.toastEls.push(element);
    while (this.toastEls.length > 3) {
      const old = this.toastEls.shift();
      old.remove();
    }
    setTimeout(() => {
      element.classList.add("out");
      setTimeout(() => element.remove(), 340);
    }, 3200);
  }

  clearToasts() {
    for (const element of this.toastEls) element.remove();
    this.toastEls = [];
    this.el.toasts.innerHTML = "";
  }

  resetRun() {
    this.last = Object.create(null);
    this.clearMotes();
    this.clearToasts();
    this.el.combo.classList.remove("show");
    this.el.bossbar.classList.add("is-hidden");
    this.el.damagewash.style.opacity = "0";
    this.el.slowwash.classList.remove("on");
    this.el.hint.classList.remove("faded");
    this.el.gameover.classList.add("is-hidden");
    this.el.pause.classList.add("is-hidden");
    this.el.endBest.classList.add("is-hidden");
  }
}

const TAU = Math.PI * 2;
const WORLD_RADIUS = 400;
const CYAN = "#6ff7f0";
const RED = "#ff4f6d";
const AMBER = "#ffc35c";
const VIOLET = "#b38bff";
const GREEN = "#9dffb0";

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const lerp = (a, b, t) => a + (b - a) * t;

function rgba(hex, alpha) {
  if (!hex || !hex.startsWith("#")) return `rgba(255,255,255,${alpha})`;
  const value = hex.slice(1);
  const full = value.length === 3 ? value.split("").map((c) => c + c).join("") : value;
  const num = parseInt(full, 16);
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r},${g},${b},${alpha})`;
}

function mulberry32(seed) {
  let t = seed >>> 0;
  return function random() {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d", { alpha: true });
    this.w = 1;
    this.h = 1;
    this.dpr = 1;
    this.cx = 0;
    this.cy = 0;
    this.scale = 1;
    this.radius = 360;
    this.portrait = false;
    this.stars = [];
    this.dust = [];
    this.cracks = [];
    this.glows = new Map();
    this.titleT = 0;
    this.ambient = [];
    this.arenaGradient = null;
    this.bgGradient = null;
    this.resize();
    this.seedAmbient();
  }

  resize() {
    const w = Math.max(1, window.innerWidth);
    const h = Math.max(1, window.innerHeight);
    const dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
    this.w = w;
    this.h = h;
    this.dpr = dpr;
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.canvas.style.width = `${w}px`;
    this.canvas.style.height = `${h}px`;
    this.portrait = h > w * 1.08;
    let radius;
    if (this.portrait) {
      radius = Math.min(w * 0.475, h * 0.295);
      this.cy = h * 0.425;
    } else {
      radius = Math.min(w * 0.405, h * 0.4);
      this.cy = h * 0.515;
    }
    if (w <= 820 && !this.portrait) {
      radius = Math.min(w * 0.34, h * 0.44);
      this.cy = h * 0.53;
    }
    this.radius = radius;
    this.cx = w / 2;
    this.scale = radius / WORLD_RADIUS;
    this.makeGradients();
    this.seedScene();
  }

  makeGradients() {
    const ctx = this.ctx;
    const arena = ctx.createRadialGradient(0, 0, 0, 0, 0, WORLD_RADIUS);
    arena.addColorStop(0, "rgba(11, 33, 44, 0.97)");
    arena.addColorStop(0.42, "rgba(7, 20, 31, 0.96)");
    arena.addColorStop(0.78, "rgba(4, 11, 20, 0.98)");
    arena.addColorStop(1, "rgba(2, 5, 11, 0.99)");
    this.arenaGradient = arena;

    const bg = ctx.createRadialGradient(
      this.w * 0.5,
      this.h * 0.45,
      0,
      this.w * 0.5,
      this.h * 0.5,
      Math.max(this.w, this.h) * 0.78
    );
    bg.addColorStop(0, "#0a1726");
    bg.addColorStop(0.46, "#050b14");
    bg.addColorStop(1, "#010308");
    this.bgGradient = bg;
  }

  seedScene() {
    const random = mulberry32(1337 + Math.round(this.w + this.h));
    this.stars = Array.from({ length: 110 }, () => ({
      x: random() * this.w,
      y: random() * this.h,
      size: 0.5 + random() * 1.5,
      alpha: 0.12 + random() * 0.55,
      phase: random() * TAU,
      drift: 2 + random() * 6,
      tint: random() < 0.18 ? "red" : random() < 0.4 ? "cyan" : "white",
    }));
    this.dust = Array.from({ length: 42 }, () => ({
      x: random() * this.w,
      y: random() * this.h,
      r: 0.6 + random() * 2.2,
      speed: 4 + random() * 12,
      phase: random() * TAU,
      alpha: 0.05 + random() * 0.16,
      tint: random() < 0.2 ? AMBER : CYAN,
    }));

    this.cracks = [];
    const crackRandom = mulberry32(91);
    for (let c = 0; c < 6; c += 1) {
      const angle = crackRandom() * TAU;
      const start = 60 + crackRandom() * 240;
      const points = [];
      let r = start;
      let a = angle;
      for (let i = 0; i < 6; i += 1) {
        points.push([Math.cos(a) * r, Math.sin(a) * r]);
        r += 24 + crackRandom() * 45;
        a += (crackRandom() - 0.5) * 0.32;
      }
      this.cracks.push({
        points,
        color: crackRandom() < 0.3 ? "rgba(255,79,109,0.16)" : "rgba(111,247,240,0.1)",
        width: 0.7 + crackRandom() * 1.3,
      });
    }
  }

  seedAmbient() {
    const random = mulberry32(77);
    this.ambient = Array.from({ length: 28 }, () => ({
      angle: random() * TAU,
      radius: 120 + random() * 260,
      speed: 0.05 + random() * 0.18,
      size: 0.8 + random() * 2.2,
      phase: random() * TAU,
      color: random() < 0.3 ? RED : random() < 0.5 ? AMBER : CYAN,
    }));
  }

  glowSprite(color) {
    if (this.glows.has(color)) return this.glows.get(color);
    const canvas = document.createElement("canvas");
    canvas.width = 64;
    canvas.height = 64;
    const ctx = canvas.getContext("2d");
    const gradient = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
    gradient.addColorStop(0, rgba(color, 0.95));
    gradient.addColorStop(0.18, rgba(color, 0.68));
    gradient.addColorStop(0.45, rgba(color, 0.22));
    gradient.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 64, 64);
    this.glows.set(color, canvas);
    return canvas;
  }

  drawGlow(x, y, size, color, alpha = 1) {
    const sprite = this.glowSprite(color);
    const ctx = this.ctx;
    const previous = ctx.globalAlpha;
    ctx.globalAlpha = previous * alpha;
    ctx.drawImage(sprite, x - size / 2, y - size / 2, size, size);
    ctx.globalAlpha = previous;
  }

  screenToWorld(x, y) {
    return {
      x: (x - this.cx) / this.scale,
      y: (y - this.cy) / this.scale,
    };
  }

  render(game, dt, app) {
    const ctx = this.ctx;
    const { w, h, dpr } = this;
    this.titleT += dt;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    this.drawBackdrop(game, dt);

    const shake = game.shake || 0;
    const sx = (Math.random() - 0.5) * shake;
    const sy = (Math.random() - 0.5) * shake;
    ctx.save();
    ctx.translate(this.cx + sx, this.cy + sy);
    ctx.scale(this.scale, this.scale);

    this.drawArena(game, app);
    this.drawRings(game);
    if (app.state === "title") {
      this.drawTitleScene(game, app);
    } else {
      this.drawPickups(game);
      this.drawEnemies(game);
      this.drawBoss(game);
      this.drawPlayer(game, app);
      this.drawBullets(game);
      this.drawParticles(game);
      this.drawTexts(game);
    }
    ctx.restore();

    this.drawScreenEffects(game, app);
    if (app.touchMode && (app.state === "playing" || app.state === "paused")) {
      this.drawSticks(app, game);
    }
  }

  drawBackdrop(game, dt) {
    const ctx = this.ctx;
    const { w, h } = this;
    const t = this.titleT;
    ctx.fillStyle = this.bgGradient || "#04060c";
    ctx.fillRect(0, 0, w, h);

    // Faint radial lift behind the arena.
    const glow = ctx.createRadialGradient(this.cx, this.cy, 0, this.cx, this.cy, this.radius * 1.35);
    const pressure = Math.min(1, (game.debt.length + (game.boss ? 2 : 0)) / 8);
    glow.addColorStop(0, `rgba(18, 78, 88, ${0.22 + pressure * 0.05})`);
    glow.addColorStop(0.5, "rgba(8, 34, 44, 0.12)");
    glow.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, w, h);

    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const star of this.stars) {
      const sway = Math.sin(t * 0.16 + star.phase) * star.drift;
      const x = star.x + sway;
      const y = (star.y + t * star.drift * 0.45) % (h + 20) - 10;
      const alpha = star.alpha * (0.55 + 0.45 * Math.sin(t * 0.8 + star.phase));
      ctx.fillStyle =
        star.tint === "red"
          ? `rgba(255, 120, 140, ${alpha * 0.7})`
          : star.tint === "cyan"
            ? `rgba(111, 247, 240, ${alpha * 0.7})`
            : `rgba(220, 242, 255, ${alpha})`;
      ctx.beginPath();
      ctx.arc(x, y, star.size, 0, TAU);
      ctx.fill();
    }
    for (const mote of this.dust) {
      const x = (mote.x + t * mote.speed * 0.35 + Math.sin(t * 0.4 + mote.phase) * 12) % (w + 40) - 20;
      const y = (mote.y - t * mote.speed + h + 20) % (h + 40) - 20;
      ctx.fillStyle = rgba(mote.tint, mote.alpha);
      ctx.beginPath();
      ctx.arc(x, y, mote.r, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // Slow drifting horizon lines on the far side of the arena.
    ctx.save();
    ctx.strokeStyle = "rgba(111, 247, 240, 0.028)";
    ctx.lineWidth = 1;
    for (let i = 0; i < 8; i += 1) {
      const y = ((t * 5 + i * 90) % (h + 200)) - 100;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y + Math.sin(i) * 30);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawArena(game, app) {
    const ctx = this.ctx;
    const R = WORLD_RADIUS;
    const t = this.titleT;
    const pending = game.debt.length;
    const activeCollectors = game.enemies.reduce(
      (n, enemy) => n + (enemy.type === "collector" && enemy.alive ? 1 : 0),
      0
    );
    const pressure = Math.min(1, (pending * 0.55 + activeCollectors * 0.35 + (game.boss ? 0.6 : 0)) / 4);
    const pulse = 0.5 + 0.5 * Math.sin(t * 2.2);

    // Outer aura
    const aura = ctx.createRadialGradient(0, 0, R * 0.72, 0, 0, R * 1.12);
    aura.addColorStop(0, "rgba(111,247,240,0)");
    aura.addColorStop(0.74, `rgba(111,247,240,${0.03 + pressure * 0.02})`);
    aura.addColorStop(0.9, `rgba(255,79,109,${pressure * 0.09})`);
    aura.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = aura;
    ctx.beginPath();
    ctx.arc(0, 0, R * 1.13, 0, TAU);
    ctx.fill();

    // Floor
    ctx.fillStyle = this.arenaGradient;
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, TAU);
    ctx.fill();

    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, TAU);
    ctx.clip();

    // Concentric clock rings.
    const rings = [0.14, 0.26, 0.38, 0.5, 0.62, 0.74, 0.85, 0.94];
    rings.forEach((fraction, index) => {
      ctx.strokeStyle = index === rings.length - 1
        ? `rgba(111,247,240,${0.16 + pressure * 0.12})`
        : `rgba(111,247,240,${0.035 + index * 0.006})`;
      ctx.lineWidth = index === rings.length - 1 ? 1.4 : 0.8;
      ctx.beginPath();
      ctx.arc(0, 0, R * fraction, 0, TAU);
      ctx.stroke();
    });

    // Radial spokes.
    ctx.strokeStyle = "rgba(111,247,240,0.035)";
    ctx.lineWidth = 0.7;
    for (let i = 0; i < 24; i += 1) {
      const angle = (i / 24) * TAU;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * R * 0.15, Math.sin(angle) * R * 0.15);
      ctx.lineTo(Math.cos(angle) * R * 0.955, Math.sin(angle) * R * 0.955);
      ctx.stroke();
    }

    // Edge ticks.
    for (let i = 0; i < 72; i += 1) {
      const angle = (i / 72) * TAU;
      const major = i % 6 === 0;
      const inner = R * (major ? 0.952 : 0.972);
      const outer = R * 0.99;
      ctx.strokeStyle = major ? `rgba(111,247,240,${0.16 + pressure * 0.2})` : "rgba(111,247,240,0.055)";
      ctx.lineWidth = major ? 1.4 : 0.8;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
      ctx.lineTo(Math.cos(angle) * outer, Math.sin(angle) * outer);
      ctx.stroke();
    }

    // Clock numerals.
    const numerals = ["XII", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI"];
    ctx.font = "500 12px 'SFMono-Regular', 'Liberation Mono', monospace";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    numerals.forEach((label, index) => {
      const angle = -Math.PI / 2 + (index / 12) * TAU;
      ctx.fillStyle = `rgba(160, 226, 228, ${0.09 + pressure * 0.05})`;
      ctx.fillText(label, Math.cos(angle) * (R - 24), Math.sin(angle) * (R - 24));
    });

    // Cracks in the clock face.
    for (const crack of this.cracks) {
      ctx.strokeStyle = crack.color;
      ctx.lineWidth = crack.width;
      ctx.beginPath();
      crack.points.forEach((point, index) => {
        if (index === 0) ctx.moveTo(point[0], point[1]);
        else ctx.lineTo(point[0], point[1]);
      });
      ctx.stroke();
    }

    // Central sigil.
    ctx.strokeStyle = "rgba(111,247,240,0.09)";
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    ctx.arc(0, 0, 132, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([3, 9]);
    ctx.strokeStyle = `rgba(255,79,109,${0.1 + pressure * 0.12})`;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(0, 0, 152, t * 0.04, t * 0.04 + TAU * 0.72);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.strokeStyle = "rgba(111,247,240,0.12)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, 66, 0, TAU);
    ctx.stroke();

    // Clock hands — the minute hand spins while time is stolen.
    const stolenBonus = game.stolen ? game.stolen * 0.22 : 0;
    const hourAngle = -Math.PI / 2 + t * 0.035;
    const minuteAngle = -Math.PI / 2 + t * 0.22 + stolenBonus;
    ctx.strokeStyle = "rgba(180, 255, 250, 0.16)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(hourAngle) * 42, Math.sin(hourAngle) * 42);
    ctx.stroke();
    ctx.strokeStyle = `rgba(255,120,140,${0.18 + pressure * 0.2})`;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(minuteAngle) * 72, Math.sin(minuteAngle) * 72);
    ctx.stroke();
    ctx.fillStyle = "rgba(111,247,240,0.3)";
    ctx.beginPath();
    ctx.arc(0, 0, 3, 0, TAU);
    ctx.fill();

    // Debt pressure crawls around the rim.
    if (pressure > 0.02) {
      ctx.globalCompositeOperation = "lighter";
      const arcLength = TAU * 0.12 + pressure * TAU * 0.52;
      const arcStart = t * 0.35;
      for (let i = 0; i < 3; i += 1) {
        ctx.strokeStyle = `rgba(255,79,109,${(0.12 + pressure * 0.22) * (0.6 + 0.4 * Math.sin(t * 1.6 + i))})`;
        ctx.lineWidth = 2 + i;
        ctx.beginPath();
        ctx.arc(0, 0, R - 7 - i * 5, arcStart + i * 0.5, arcStart + i * 0.5 + arcLength);
        ctx.stroke();
      }
      ctx.globalCompositeOperation = "source-over";
    }
    ctx.restore();

    // Outer boundary.
    ctx.strokeStyle = `rgba(111,247,240,${0.22 + pressure * 0.25})`;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = `rgba(255,79,109,${pressure * 0.18 * (0.6 + 0.4 * pulse)})`;
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.arc(0, 0, R + 6, 0, TAU);
    ctx.stroke();

    // Rotating marker shards at the edge.
    ctx.save();
    ctx.rotate(t * 0.08);
    for (let i = 0; i < 4; i += 1) {
      ctx.rotate(TAU / 4);
      ctx.fillStyle = `rgba(255,79,109,${0.14 + pressure * 0.2})`;
      ctx.beginPath();
      ctx.moveTo(R + 1, -4);
      ctx.lineTo(R + 16, 0);
      ctx.lineTo(R + 1, 4);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    if (game.boss && !game.boss.dead) {
      ctx.strokeStyle = `rgba(179,139,255,${0.12 + pulse * 0.1})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, R * 0.68, 0, TAU);
      ctx.stroke();
    }
  }

  drawTitleScene(game, app) {
    const ctx = this.ctx;
    const t = this.titleT;
    const p = game.player;

    // Ambient time dust.
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const mote of this.ambient) {
      const angle = mote.angle + t * mote.speed * 0.12;
      const radius = mote.radius + Math.sin(t * 0.4 + mote.phase) * 16;
      const x = Math.cos(angle) * radius;
      const y = Math.sin(angle) * radius;
      this.drawGlow(x, y, mote.size * 9, mote.color, 0.16 + 0.1 * Math.sin(t + mote.phase));
    }
    ctx.restore();

    // Future echoes pacing the rim.
    for (let i = 0; i < 3; i += 1) {
      const angle = t * 0.12 + (i / 3) * TAU;
      const x = Math.cos(angle) * 285;
      const y = Math.sin(angle) * 285;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle + Math.PI / 2);
      ctx.globalAlpha = 0.13 + 0.04 * Math.sin(t * 0.8 + i);
      this.drawShipShape(23, RED);
      ctx.restore();
    }

    // The duelist waits at the centre.
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(-Math.PI / 2 + Math.sin(t * 0.5) * 0.06);
    const breathe = 1 + Math.sin(t * 1.2) * 0.03;
    ctx.scale(breathe, breathe);
    this.drawGlow(0, 0, 110, CYAN, 0.2);
    this.drawShipShape(23, CYAN, true);
    ctx.restore();

    this.drawGlow(0, 0, 300, CYAN, 0.035);
  }

  drawRings(game) {
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const ring of game.rings) {
      const progress = 1 - ring.life / ring.maxLife;
      const radius = lerp(ring.r0, ring.r1, 1 - Math.pow(1 - progress, 2));
      const alpha = Math.max(0, ring.life / ring.maxLife) * 0.7;
      ctx.strokeStyle = rgba(ring.color, alpha * 0.35);
      ctx.lineWidth = ring.width * 2.4;
      ctx.beginPath();
      ctx.arc(ring.x, ring.y, radius, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = rgba(ring.color, alpha);
      ctx.lineWidth = ring.width;
      ctx.beginPath();
      ctx.arc(ring.x, ring.y, radius, 0, TAU);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawPickups(game) {
    const ctx = this.ctx;
    for (const pickup of game.pickups) {
      const pulse = 0.5 + 0.5 * Math.sin(pickup.t * 4);
      const alpha = pickup.life < 3 ? 0.4 + 0.6 * Math.abs(Math.sin(pickup.life * 6)) : 1;
      ctx.save();
      ctx.globalAlpha = alpha;
      this.drawGlow(pickup.x, pickup.y, 44 + pulse * 10, GREEN, 0.32);
      ctx.translate(pickup.x, pickup.y);
      ctx.rotate(pickup.t * 0.9);
      ctx.strokeStyle = GREEN;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(0, -8);
      ctx.lineTo(8, 0);
      ctx.lineTo(0, 8);
      ctx.lineTo(-8, 0);
      ctx.closePath();
      ctx.stroke();
      ctx.fillStyle = "rgba(157,255,176,0.16)";
      ctx.fill();
      ctx.rotate(-pickup.t * 0.9);
      ctx.strokeStyle = "rgba(220,255,230,0.9)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(-3, 0);
      ctx.lineTo(3, 0);
      ctx.moveTo(0, -3);
      ctx.lineTo(0, 3);
      ctx.stroke();
      ctx.restore();
    }
  }

  drawEnemies(game) {
    const ctx = this.ctx;
    for (const enemy of game.enemies) {
      if (!enemy.alive) continue;
      if (enemy.spawnT > 0) {
        this.drawPortal(enemy);
        continue;
      }
      const alpha = enemy.flash > 0 ? 1 : 1;
      ctx.save();
      ctx.globalAlpha = alpha;
      if (enemy.telegraph > 0) this.drawEnemyTelegraph(enemy, game);
      switch (enemy.type) {
        case "husk":
          this.drawHusk(enemy);
          break;
        case "gazer":
          this.drawGazer(enemy, game);
          break;
        case "brute":
          this.drawBrute(enemy);
          break;
        case "collector":
          this.drawCollector(enemy, game);
          break;
        default:
          break;
      }
      if (enemy.flash > 0) {
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        this.drawGlow(enemy.x, enemy.y, enemy.r * 4, "#ffffff", Math.min(0.8, enemy.flash * 6));
        ctx.restore();
      }
      ctx.restore();
    }
  }

  drawPortal(enemy) {
    const ctx = this.ctx;
    const t = 1 - enemy.spawnT / enemy.spawnMax;
    const radius = lerp(enemy.r * 2.6, enemy.r * 1.1, t);
    const color = enemy.color;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.translate(enemy.x, enemy.y);
    this.drawGlow(0, 0, enemy.r * 7, color, 0.3);
    ctx.rotate(this.titleT * 1.4);
    ctx.strokeStyle = rgba(color, 0.65);
    ctx.lineWidth = 1.4;
    ctx.setLineDash([4, 6]);
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    for (let i = 0; i < 3; i += 1) {
      ctx.rotate(TAU / 3);
      ctx.strokeStyle = rgba(color, 0.35);
      ctx.beginPath();
      ctx.arc(0, 0, radius * 0.72, 0, 0.7);
      ctx.stroke();
    }
    ctx.restore();
    if (enemy.type === "collector") {
      ctx.save();
      ctx.fillStyle = `rgba(255,79,109,${0.5 + 0.3 * Math.sin(this.titleT * 8)})`;
      ctx.font = "700 9px 'SFMono-Regular', monospace";
      ctx.textAlign = "center";
      ctx.fillText("COLLECTOR", enemy.x, enemy.y - enemy.r * 2.1);
      ctx.restore();
    }
  }

  drawHusk(enemy) {
    const ctx = this.ctx;
    const angle = enemy.angle || 0;
    this.drawGlow(enemy.x, enemy.y, enemy.r * 5.4, enemy.color, 0.26);
    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.rotate(angle);
    ctx.fillStyle = "rgba(48, 9, 24, 0.85)";
    ctx.strokeStyle = enemy.color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(enemy.r * 1.25, 0);
    ctx.lineTo(-enemy.r * 0.55, enemy.r * 0.82);
    ctx.lineTo(-enemy.r * 0.15, 0);
    ctx.lineTo(-enemy.r * 0.55, -enemy.r * 0.82);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,220,230,0.75)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(enemy.r * 0.7, 0);
    ctx.lineTo(-enemy.r * 0.15, 0);
    ctx.stroke();
    ctx.fillStyle = "#ffe9ef";
    ctx.beginPath();
    ctx.arc(enemy.r * 0.35, 0, 1.7, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  drawGazer(enemy, game) {
    const ctx = this.ctx;
    const angle = Math.atan2(game.player.y - enemy.y, game.player.x - enemy.x);
    this.drawGlow(enemy.x, enemy.y, enemy.r * 5.8, enemy.color, 0.24);
    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.rotate(this.titleT * 0.5 + enemy.phase);
    ctx.strokeStyle = rgba(enemy.color, 0.6);
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 4; i += 1) {
      ctx.beginPath();
      ctx.arc(0, 0, enemy.r + 4 + i * 2.5, i * 0.6, i * 0.6 + 1.3);
      ctx.stroke();
    }
    ctx.restore();

    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.strokeStyle = enemy.color;
    ctx.lineWidth = 1.4;
    ctx.fillStyle = "rgba(32, 20, 5, 0.9)";
    ctx.beginPath();
    ctx.ellipse(0, 0, enemy.r, enemy.r * 0.78, 0, 0, TAU);
    ctx.fill();
    ctx.stroke();
    const blink = 0.55 + 0.45 * Math.abs(Math.sin(this.titleT * 1.3 + enemy.phase));
    ctx.save();
    ctx.rotate(angle);
    ctx.fillStyle = "rgba(255,235,190,0.92)";
    ctx.beginPath();
    ctx.ellipse(2, 0, enemy.r * 0.56, enemy.r * 0.4 * blink, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#2b1602";
    ctx.beginPath();
    ctx.arc(5, 0, enemy.r * 0.22 * blink + 1, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#fff6df";
    ctx.beginPath();
    ctx.arc(4, -2, 1.2, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.restore();
  }

  drawBrute(enemy) {
    const ctx = this.ctx;
    this.drawGlow(enemy.x, enemy.y, enemy.r * 5.2, enemy.color, 0.25);
    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.rotate(enemy.angle * 0.4 + this.titleT * 0.2);
    ctx.strokeStyle = "rgba(179,139,255,0.75)";
    ctx.fillStyle = "rgba(24,14,42,0.9)";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    for (let i = 0; i < 6; i += 1) {
      const angle = (i / 6) * TAU;
      const x = Math.cos(angle) * enemy.r;
      const y = Math.sin(angle) * enemy.r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.rotate(-enemy.angle * 0.8);
    for (let i = 0; i < 3; i += 1) {
      ctx.rotate(TAU / 3);
      ctx.strokeStyle = rgba(enemy.color, 0.5);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, enemy.r * 0.62, 0.2, 1.1);
      ctx.stroke();
    }
    ctx.fillStyle = "rgba(230,210,255,0.9)";
    ctx.beginPath();
    ctx.arc(0, 0, 3.4, 0, TAU);
    ctx.fill();
    ctx.restore();

    this.drawEnemyHealthBar(enemy, enemy.r * 2.2, -enemy.r - 12, "rgba(179,139,255,0.7)");
  }

  drawCollector(enemy, game) {
    const ctx = this.ctx;
    const angle = enemy.angle || 0;
    this.drawGlow(enemy.x, enemy.y, enemy.r * 6.4, RED, 0.34);
    for (let i = 1; i <= 2; i += 1) {
      ctx.save();
      ctx.globalAlpha = 0.16 / i;
      ctx.translate(enemy.x - enemy.vx * 0.035 * i, enemy.y - enemy.vy * 0.035 * i);
      ctx.rotate(angle);
      this.drawShipShape(enemy.r, RED);
      ctx.restore();
    }
    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.rotate(angle);
    ctx.strokeStyle = "rgba(255,120,140,0.55)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, enemy.r + 6, this.titleT * 1.5, this.titleT * 1.5 + 2.2);
    ctx.stroke();
    this.drawShipShape(enemy.r, RED);
    ctx.restore();

    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    ctx.rotate(-this.titleT * 2.1);
    for (let i = 0; i < 3; i += 1) {
      ctx.rotate(TAU / 3);
      ctx.fillStyle = "rgba(255,79,109,0.75)";
      ctx.beginPath();
      ctx.moveTo(enemy.r + 8, 0);
      ctx.lineTo(enemy.r + 12, -1.7);
      ctx.lineTo(enemy.r + 12, 1.7);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    this.drawEnemyHealthBar(enemy, enemy.r * 2.4, -enemy.r - 13, "rgba(255,79,109,0.85)");
  }

  drawShipShape(size, color, bright = false) {
    const ctx = this.ctx;
    ctx.fillStyle = bright ? "rgba(12,54,58,0.9)" : "rgba(42,5,15,0.82)";
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(size, 0);
    ctx.lineTo(-size * 0.48, size * 0.5);
    ctx.lineTo(-size * 0.18, 0);
    ctx.lineTo(-size * 0.48, -size * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = bright ? "#eafffd" : "rgba(255,200,210,0.9)";
    ctx.beginPath();
    ctx.arc(size * 0.2, 0, Math.max(1.4, size * 0.09), 0, TAU);
    ctx.fill();
    if (bright) {
      ctx.strokeStyle = "rgba(111,247,240,0.55)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-size * 0.28, size * 0.26);
      ctx.lineTo(-size * 0.72, size * 0.62);
      ctx.moveTo(-size * 0.28, -size * 0.26);
      ctx.lineTo(-size * 0.72, -size * 0.62);
      ctx.stroke();
    }
  }

  drawEnemyTelegraph(enemy, game) {
    const ctx = this.ctx;
    const strength = clamp(enemy.telegraph / Math.max(0.001, enemy.telegraphMax), 0, 1);
    const color =
      enemy.type === "brute" ? VIOLET : enemy.type === "gazer" ? AMBER : enemy.type === "collector" ? RED : CYAN;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    this.drawGlow(enemy.x, enemy.y, (enemy.r + 30) * 2, color, 0.1 + strength * 0.18);
    ctx.strokeStyle = rgba(color, 0.18 + strength * 0.5);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.r + 8 + strength * 8, 0, TAU);
    ctx.stroke();

    if (enemy.type === "gazer" || enemy.type === "collector") {
      const angle = Number.isFinite(enemy.lockAngle) ? enemy.lockAngle : 0;
      ctx.strokeStyle = rgba(color, 0.2 + strength * 0.35);
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 7]);
      ctx.beginPath();
      ctx.moveTo(enemy.x, enemy.y);
      ctx.lineTo(enemy.x + Math.cos(angle) * 520, enemy.y + Math.sin(angle) * 520);
      ctx.stroke();
      ctx.setLineDash([]);
    }
    if (enemy.type === "brute") {
      ctx.strokeStyle = rgba(VIOLET, 0.2 + strength * 0.4);
      for (let i = 0; i < 12; i += 1) {
        const angle = (i / 12) * TAU;
        ctx.beginPath();
        ctx.moveTo(enemy.x + Math.cos(angle) * (enemy.r + 6), enemy.y + Math.sin(angle) * (enemy.r + 6));
        ctx.lineTo(enemy.x + Math.cos(angle) * (enemy.r + 22), enemy.y + Math.sin(angle) * (enemy.r + 22));
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawEnemyHealthBar(enemy, width, offsetY, color) {
    const ctx = this.ctx;
    const ratio = clamp(enemy.hp / enemy.maxHp, 0, 1);
    const x = enemy.x - width / 2;
    const y = enemy.y + offsetY;
    ctx.save();
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(x, y, width, 2.6);
    ctx.fillStyle = color;
    ctx.fillRect(x, y, width * ratio, 2.6);
    ctx.restore();
  }

  drawBoss(game) {
    const boss = game.boss;
    if (!boss) return;
    const ctx = this.ctx;
    if (boss.spawnT > 0) {
      const t = 1 - boss.spawnT / boss.spawnMax;
      ctx.save();
      ctx.translate(boss.x, boss.y);
      ctx.globalCompositeOperation = "lighter";
      this.drawGlow(0, 0, 400, RED, 0.25 + t * 0.2);
      ctx.rotate(this.titleT * 2);
      for (let i = 0; i < 4; i += 1) {
        ctx.rotate(TAU / 4);
        ctx.strokeStyle = `rgba(255,79,109,${0.2 + t * 0.5})`;
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.arc(0, 0, 160 - t * 80, 0, 1.2);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }

    const pulse = 0.5 + 0.5 * Math.sin(this.titleT * 2.4);
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    this.drawGlow(boss.x, boss.y, boss.r * 8, RED, 0.2 + pulse * 0.06);
    ctx.restore();

    ctx.save();
    ctx.translate(boss.x, boss.y);
    ctx.rotate(boss.angle * 0.3);
    // Outer gear ring
    ctx.strokeStyle = "rgba(255,120,140,0.55)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, boss.r + 12, 0, TAU);
    ctx.stroke();
    for (let i = 0; i < 20; i += 1) {
      const angle = (i / 20) * TAU;
      ctx.strokeStyle = i % 5 === 0 ? "rgba(255,200,210,0.65)" : "rgba(255,79,109,0.4)";
      ctx.lineWidth = i % 5 === 0 ? 1.6 : 0.9;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * (boss.r + 12), Math.sin(angle) * (boss.r + 12));
      ctx.lineTo(Math.cos(angle) * (boss.r + (i % 5 === 0 ? 22 : 18)), Math.sin(angle) * (boss.r + (i % 5 === 0 ? 22 : 18)));
      ctx.stroke();
    }
    ctx.rotate(-boss.angle * 0.8 + this.titleT * 0.1);
    ctx.strokeStyle = "rgba(179,139,255,0.45)";
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 6]);
    ctx.beginPath();
    ctx.arc(0, 0, boss.r + 34, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    if (boss.phase === 2) {
      ctx.strokeStyle = `rgba(255,79,109,${0.2 + pulse * 0.2})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(0, 0, boss.r + 46, this.titleT * 0.7, this.titleT * 0.7 + 4.8);
      ctx.stroke();
    }
    ctx.restore();

    // Face / clock body
    ctx.save();
    ctx.translate(boss.x, boss.y);
    const body = ctx.createRadialGradient(0, 0, 0, 0, 0, boss.r);
    body.addColorStop(0, "rgba(58, 16, 30, 0.98)");
    body.addColorStop(0.7, "rgba(20, 8, 18, 0.98)");
    body.addColorStop(1, "rgba(8, 3, 9, 1)");
    ctx.fillStyle = body;
    ctx.strokeStyle = "rgba(255,140,155,0.7)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, boss.r, 0, TAU);
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = "rgba(255,170,185,0.22)";
    ctx.lineWidth = 1;
    for (let i = 0; i < 12; i += 1) {
      const angle = (i / 12) * TAU;
      const inner = boss.r * (i % 3 === 0 ? 0.78 : 0.86);
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
      ctx.lineTo(Math.cos(angle) * boss.r * 0.94, Math.sin(angle) * boss.r * 0.94);
      ctx.stroke();
    }

    // Eye
    const toPlayer = Math.atan2(game.player.y - boss.y, game.player.x - boss.x);
    ctx.save();
    ctx.rotate(toPlayer);
    ctx.fillStyle = "rgba(255, 60, 90, 0.2)";
    ctx.beginPath();
    ctx.ellipse(0, 0, boss.r * 0.52, boss.r * 0.34, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(255,120,140,0.7)";
    ctx.stroke();
    ctx.fillStyle = "rgba(255, 70, 95, 0.92)";
    ctx.beginPath();
    ctx.arc(boss.r * 0.12, 0, boss.r * 0.18 + pulse * 1.5, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#fff0f2";
    ctx.beginPath();
    ctx.arc(boss.r * 0.1, -2, 1.8, 0, TAU);
    ctx.fill();
    ctx.restore();

    // Hands
    ctx.rotate(this.titleT * 0.12);
    ctx.strokeStyle = "rgba(255,200,210,0.5)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(-1.2) * boss.r * 0.5, Math.sin(-1.2) * boss.r * 0.5);
    ctx.stroke();
    ctx.lineWidth = 1.2;
    ctx.strokeStyle = "rgba(255,79,109,0.65)";
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(this.titleT * 0.4) * boss.r * 0.72, Math.sin(this.titleT * 0.4) * boss.r * 0.72);
    ctx.stroke();
    ctx.restore();

    if (boss.telegraph > 0) {
      const strength = 1 - boss.telegraph / Math.max(0.001, boss.telegraphMax);
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.strokeStyle = `rgba(255,79,109,${0.2 + strength * 0.45})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(boss.x, boss.y, boss.r + 25 + (1 - strength) * 40, 0, TAU);
      ctx.stroke();
      if (boss.pattern === "aimed") {
        const angle = Number.isFinite(boss.lockAngle) ? boss.lockAngle : 0;
        ctx.strokeStyle = `rgba(255,176,189,${0.2 + strength * 0.35})`;
        ctx.setLineDash([6, 9]);
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(boss.x, boss.y);
        ctx.lineTo(boss.x + Math.cos(angle) * 560, boss.y + Math.sin(angle) * 560);
        ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.restore();
    }

    if (boss.flash > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      this.drawGlow(boss.x, boss.y, boss.r * 4, "#ffffff", 0.7);
      ctx.restore();
    }

    ctx.save();
    ctx.textAlign = "center";
    ctx.font = "700 10px 'SFMono-Regular', monospace";
    ctx.fillStyle = `rgba(255,150,165,${0.5 + pulse * 0.2})`;
    ctx.fillText("THE AUDITOR", boss.x, boss.y - boss.r - 30);
    ctx.restore();
  }

  drawPlayer(game, app) {
    const ctx = this.ctx;
    const p = game.player;
    if (p.dead) return;
    const over = p.overdriveGlow || 0;

    // Movement trail
    if (p.trail.length > 2) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (let i = 1; i < p.trail.length; i += 1) {
        const point = p.trail[i];
        const alpha = (1 - i / p.trail.length) * 0.12;
        this.drawGlow(point.x, point.y, 20 - i, CYAN, alpha);
      }
      ctx.restore();
    }

    // Future echo while time is slow.
    if (game.timeScale < 0.8 && game.echo.length > 3) {
      const target = game.time - 0.52;
      let sample = game.echo[0];
      for (const entry of game.echo) {
        if (entry.t <= target) sample = entry;
        else break;
      }
      if (sample) {
        ctx.save();
        ctx.globalAlpha = 0.22 + 0.1 * Math.sin(this.titleT * 9);
        ctx.translate(sample.x, sample.y);
        ctx.rotate(sample.angle);
        this.drawShipShape(22, RED);
        ctx.restore();
        ctx.save();
        ctx.globalAlpha = 0.08;
        ctx.strokeStyle = RED;
        ctx.setLineDash([2, 6]);
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(sample.x, sample.y);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.restore();
      }
    }

    // Overclock aura
    if (over > 0.02) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = over;
      this.drawGlow(p.x, p.y, 130, AMBER, 0.18 + 0.08 * Math.sin(this.titleT * 8));
      ctx.translate(p.x, p.y);
      ctx.rotate(this.titleT * 3.4);
      for (let i = 0; i < 3; i += 1) {
        ctx.rotate(TAU / 3);
        ctx.fillStyle = "rgba(255,215,106,0.8)";
        ctx.beginPath();
        ctx.moveTo(30, 0);
        ctx.lineTo(35, -2);
        ctx.lineTo(35, 2);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    // Dash cooldown ring
    if (p.dashCd > 0) {
      const ratio = 1 - p.dashCd / 2;
      ctx.save();
      ctx.strokeStyle = "rgba(111,247,240,0.13)";
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 28, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = "rgba(111,247,240,0.5)";
      ctx.beginPath();
      ctx.arc(p.x, p.y, 28, -Math.PI / 2, -Math.PI / 2 + ratio * TAU);
      ctx.stroke();
      ctx.restore();
    }

    this.drawGlow(p.x, p.y, 96, over > 0.5 ? AMBER : CYAN, 0.22);

    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.angle);
    if (p.invuln > 0 && Math.floor(p.invuln * 24) % 2 === 0) ctx.globalAlpha = 0.55;
    this.drawShipShape(23, over > 0.5 ? AMBER : CYAN, true);

    // Blink arc
    ctx.strokeStyle = over > 0.5 ? "rgba(255,215,106,0.5)" : "rgba(111,247,240,0.45)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(0, 0, 19, -0.6, 0.6);
    ctx.stroke();
    ctx.restore();

    // Aim tick
    ctx.save();
    ctx.globalAlpha = 0.25;
    ctx.strokeStyle = over > 0.5 ? AMBER : CYAN;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 6]);
    ctx.beginPath();
    ctx.moveTo(p.x + Math.cos(p.angle) * 30, p.y + Math.sin(p.angle) * 30);
    ctx.lineTo(p.x + Math.cos(p.angle) * 52, p.y + Math.sin(p.angle) * 52);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  drawBullets(game) {
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const bullet of game.bullets) {
      const friendly = bullet.friendly;
      const speed = Math.hypot(bullet.vx, bullet.vy) || 1;
      const tail = friendly ? 22 : 14;
      const tx = bullet.x - (bullet.vx / speed) * tail;
      const ty = bullet.y - (bullet.vy / speed) * tail;
      const gradient = ctx.createLinearGradient(tx, ty, bullet.x, bullet.y);
      gradient.addColorStop(0, rgba(bullet.color, 0));
      gradient.addColorStop(1, rgba(bullet.color, friendly ? 0.8 : 0.55));
      ctx.strokeStyle = gradient;
      ctx.lineWidth = friendly ? 2.6 : 2;
      ctx.beginPath();
      ctx.moveTo(tx, ty);
      ctx.lineTo(bullet.x, bullet.y);
      ctx.stroke();
      this.drawGlow(bullet.x, bullet.y, friendly ? 24 : 19, bullet.color, friendly ? 0.5 : 0.4);
      ctx.fillStyle = friendly && bullet.overclocked ? "#fff4cc" : "#ffffff";
      ctx.beginPath();
      ctx.arc(bullet.x, bullet.y, friendly ? 2.2 : 1.8, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawParticles(game) {
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const particle of game.particles) {
      const alpha = clamp(particle.life / particle.maxLife, 0, 1);
      if (particle.glow) this.drawGlow(particle.x, particle.y, particle.size * 8, particle.color, alpha * 0.3);
      if (particle.type === "shard") {
        ctx.save();
        ctx.translate(particle.x, particle.y);
        ctx.rotate(particle.rot);
        ctx.fillStyle = rgba(particle.color, alpha);
        ctx.fillRect(-particle.size, -particle.size * 0.4, particle.size * 2, particle.size * 0.8);
        ctx.restore();
      } else {
        ctx.fillStyle = rgba(particle.color, alpha);
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size * (0.4 + alpha * 0.6), 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  drawTexts(game) {
    const ctx = this.ctx;
    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (const text of game.texts) {
      const alpha = clamp(text.life / text.maxLife, 0, 1);
      ctx.font = `700 ${text.size}px 'SFMono-Regular', 'Liberation Mono', monospace`;
      ctx.fillStyle = rgba(text.color, alpha);
      ctx.shadowColor = rgba(text.color, alpha * 0.7);
      ctx.shadowBlur = 8;
      ctx.fillText(text.text, text.x, text.y);
    }
    ctx.restore();
  }

  drawScreenEffects(game, app) {
    const ctx = this.ctx;
    const { w, h } = this;
    const slow = clamp((1 - game.timeScale) / 0.8, 0, 1);

    if (slow > 0.02 && app.state !== "title") {
      ctx.save();
      ctx.fillStyle = `rgba(40, 110, 255, ${slow * 0.035})`;
      ctx.fillRect(0, 0, w, h);
      ctx.globalCompositeOperation = "lighter";

      const cx = w / 2;
      const cy = h * 0.5;
      const radius = Math.min(w, h) * 0.33;
      ctx.strokeStyle = `rgba(150, 235, 255, ${slow * 0.045})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = `rgba(150, 235, 255, ${slow * 0.035})`;
      ctx.beginPath();
      ctx.arc(cx, cy, radius * 0.72, 0, TAU);
      ctx.stroke();
      for (let i = 0; i < 60; i += 1) {
        const angle = (i / 60) * TAU;
        ctx.globalAlpha = slow * (i % 5 === 0 ? 0.13 : 0.05);
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(angle) * radius * 0.94, cy + Math.sin(angle) * radius * 0.94);
        ctx.lineTo(cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius);
        ctx.stroke();
      }
      ctx.globalAlpha = slow * 0.16;
      ctx.strokeStyle = "rgba(255,255,255,0.4)";
      ctx.lineWidth = 1.5;
      const hand = game.time * 3.2;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(hand) * radius * 0.62, cy + Math.sin(hand) * radius * 0.62);
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(hand * 0.18 - 1.2) * radius * 0.36, cy + Math.sin(hand * 0.18 - 1.2) * radius * 0.36);
      ctx.stroke();
      ctx.restore();
    }

    // Low health vignette.
    if (game.player.hp <= 32 && game.player.hp > 0 && app.state !== "title") {
      const pulse = 0.35 + 0.35 * Math.sin(this.titleT * 4);
      const gradient = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.25, w / 2, h / 2, Math.max(w, h) * 0.72);
      gradient.addColorStop(0, "rgba(255,40,70,0)");
      gradient.addColorStop(1, `rgba(255,30,60,${0.1 + pulse * 0.08})`);
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);
    }

    // Cinematic letterbox flash on death/victory.
    if (game.status === "dying" || game.status === "victory") {
      const amount = game.status === "dying" ? 0.55 : 0.2;
      const gradient = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.7);
      gradient.addColorStop(0, "rgba(0,0,0,0)");
      gradient.addColorStop(1, `rgba(0,0,0,${amount})`);
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);
    }
  }

  drawSticks(app, game) {
    const ctx = this.ctx;
    const { w, h } = this;
    const defaultX = Math.max(88, w * 0.22);
    const baseY = h - 96;
    const sticks = app.input?.sticks;
    const drawStick = (name, defaultXPos, label) => {
      const stick = sticks?.[name];
      const active = stick?.active;
      const x = active ? stick.originX : defaultXPos;
      const y = active ? stick.originY : baseY;
      const nx = active ? stick.x : x;
      const ny = active ? stick.y : y;
      ctx.save();
      ctx.globalAlpha = active ? 0.75 : 0.28;
      ctx.strokeStyle = "rgba(111,247,240,0.5)";
      ctx.fillStyle = "rgba(5,12,20,0.28)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(x, y, 48, 0, TAU);
      ctx.fill();
      ctx.stroke();
      ctx.strokeStyle = "rgba(111,247,240,0.18)";
      ctx.beginPath();
      ctx.arc(x, y, 34, 0, TAU);
      ctx.stroke();
      const dx = nx - x;
      const dy = ny - y;
      const dist = Math.hypot(dx, dy);
      const max = 34;
      const scale = dist > max ? max / dist : 1;
      ctx.globalAlpha = active ? 0.95 : 0.5;
      this.drawGlow(x + dx * scale, y + dy * scale, 62, game.input.slow && name === "aim" ? AMBER : CYAN, 0.35);
      ctx.fillStyle = "rgba(160, 255, 250, 0.2)";
      ctx.strokeStyle = "rgba(160,255,250,0.8)";
      ctx.beginPath();
      ctx.arc(x + dx * scale, y + dy * scale, 21, 0, TAU);
      ctx.fill();
      ctx.stroke();
      if (!active) {
        ctx.globalAlpha = 0.55;
        ctx.fillStyle = "rgba(180, 220, 228, 0.65)";
        ctx.font = "700 9px 'SFMono-Regular', monospace";
        ctx.textAlign = "center";
        ctx.fillText(label, x, y + 66);
      }
      ctx.restore();
    };
    drawStick("move", defaultX, "MOVE");
    drawStick("aim", w - defaultX, "AIM · FIRE");
  }
}

content.text:
Now main.js: input, state, loop, UI wiring, test hooks.

Input design:

```js
const input = {
 keys: new Set(),
 mouse: {x:w/2,y:h/2,down:false,right:false},
 sticks: {
   move: {active:false, originX:0, originY:0, x:0, y:0, pointerId:null, dx:0,dy:0},
   aim: {...}
 },
 touchMode: false,
};
```

On resize, renderer.resize(); update bodies.

Pointer handling:
- canvas pointerdown (pointerType mouse): record mouse; mousedown left fires (if state playing). Right button sets slowMouse.
- For touch:
  - if within lower area? Use pointerdown on canvas. Determine zone by x < w/2 → move else aim. But the title overlay/ HUD etc intercept. Canvas is behind overlays; when game playing HUD pointer-events none except buttons. Touch area over canvas works.
  - Buttons TIME/BLINK intercept pointer events; stopPropagation inherent because they're DOM elements not canvas.
  - The aim joystick should only start if not on a button. Canvas listener won't get button events, good.
  - Mark pointerId → stick; set origin at touch; active; x,y.
  - pointermove update stick with clamping? Keep raw, renderer clamps nub; movement uses vector clamp magnitude 1.
  - pointerup/cancel: deactivate.
- Use pointer capture on canvas for each pointer? `canvas.setPointerCapture(e.pointerId)` ensures moves. But multiple pointers; capture per pointer works. However when touching, browser may cancel due gestures; CSS touch-action none.
- For mouse aiming: pointermove update. aim angle computed from world coords each frame. `mouse.down` set on pointerdown left. On pointerup anywhere (window) clear. Right button for slow; contextmenu prevented.
- Buttons slow: pointerdown → slowButton=true; pointerup/leave/cancel → false. Use pointer capture. Add both pointerdown/up on button. `touch-action:none`.
- Dash button: pointerdown → dashQueued=true; also feedback.
- Space keydown → dashQueued=true (if not repeat); Shift keydown/up sets slowKey; P/Esc pause; M mute.
- On window blur: clear keys/buttons; pause? Maybe don't auto-pause to avoid capture weirdness. Add visibilitychange → pause if hidden and playing.
- Mouse fire: left down on canvas or window? Clicking HUD icons shouldn't fire. Add canvas mousedown for fire, window mouseup. Mouse aim track window.
- For desktop, if mouse leaves window, keep last aim.

Touch mode detection:
```js
const coarse = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0 || innerWidth <= 820;
```
On capture mobile, innerWidth 390 → true; touch controls show and use pointer events with mouse too (Playwright click won't use sticks but auto-fire). For mobile emulation, game's aim on touch: auto-aim nearest enemy and auto-fire. Main computes:
- If touchMode:
  - move from left stick; aim from right stick if magnitude>0.2 else autoAim nearest enemy.
  - fire = touchMode && (state playing) && (aimStick active || nearest enemy exists) && !slowButton? Firing while slow is fine.
  - aimAngle set.
- But if a player wants to stop firing, they can't; okay for mobile.
- Also auto-aim only within arena; nearest enemy alive and spawnT<=0; else boss; else keep angle.
- Delay auto-fire until wave starts? Fire at nothing wastes; no cost.

Desktop:
- aim from mouse world; fire = mouse.down.
- move from keys.

Per frame:
```js
function updateInput() {
  const g=game;
  let mx=0,my=0;
  if (keys W/ArrowUp) my-=1; etc
  if (touchMove active) { mx = clamp(dx/40,-1,1); my = ... }
  ...
  g.input.moveX=mx...
  if (touchMode) {
    if aim stick active { angle=atan2(dy,dx); fire=true }
    else { autoAim; fire = hasTarget }
    // if autoAim none, aim toward move or last
    g.input.slow = slowButton || keys Shift;
  } else {
    const world = renderer.screenToWorld(mouse.x, mouse.y);
    g.input.aimAngle = atan2(world.y - p.y, world.x - p.x);
    g.input.fire = mouse.down;
    g.input.slow = keys Shift || mouse.right;
  }
  if (dashQueued) { g.input.dashPressed=true; dashQueued=false; } else g.input.dashPressed=false;
}
```
Careful: dash queued should persist until game consumes; if we set only for a frame, game consumes same frame. Main calls updateInput then game.update. Good. If game paused, we clear queue.

When game not playing (dying), input fire etc; game ignores. Set slow false.

Touch buttons held: `slowHeld` boolean.

Auto-aim:
```js
let best=null,bestD=Infinity;
for enemies alive spawnT<=0 dist; also boss;
if best, angle=atan2(...)
```
If aim stick active but magnitude small, use auto-aim? If active > 0.25 use manual; else auto. Fire = touchMode && (manual or target exists). For manual, firing always (even no target) - okay.

Mobile slow button + auto-fire: user can hold TIME while auto-fire continues, good.

Dash: touch button queues dash; direction from move stick or aim.

Pause:
```js
function togglePause() {
 if app.state==='playing' { app.state='paused'; ui.showPause(); audio.setPaused(true); clear input }
 else if paused { resume }
}
```
Game doesn't update; renderer keeps rendering with game frozen; UI update still called? call ui.update(game, paused) each frame; but HUD hidden? We'll hide? Keep HUD visible behind modal. ui.update with paused true; touch controls hidden via update. Fine.

When pause, audio context suspend; on resume resume. Music interval still runs while suspended? scheduler uses currentTime frozen; it might queue notes far ahead? `setInterval` continues but `nextNoteAt` stops advancing relative? ctx.currentTime suspended → scheduler while loop schedules until ahead; nextNoteAt could grow far beyond currentTime, and on resume it would catch up with a burst? Actually if currentTime frozen and nextNoteAt ahead, loop stops; no queue. On resume, fine. Good.
- Also `audio.setPaused(false)` on resume.
- Pause overlay "Sound" toggles.

Start game:
```js
function startGame() {
  ui.hideTitle(); ui.resetRun(); ui.setPlaying(true);
  game.onSfx=audio.sfx...; callbacks set once.
  game.reset();
  app.state='playing';
  app.runStart=performance.now();
  audio.init(); audio.setPaused(false); audio.startMusic();
  ui.setMuted(audio.muted);
  input reset.
}
```
Order: `game.reset()` calls onBanner/onToast. UI reset before reset so toasts not cleared. Do `ui.resetRun()` then `game.reset()` then `ui.setPlaying(true)` then hideTitle. But game.reset's toast happens while HUD hidden; toast container visible anyway. Fine. Show HUD after. Also banner visible.

Main sets callbacks before any reset:
```js
game.onSfx=(name,opts)=>audio.sfx(name,opts)
game.onToast=(text,tone)=>ui.toast(text,tone)
game.onBanner=(title,sub)=>ui.banner(title,sub)
game.onSlowChange=(active)=>audio.setSlow(active)
```
Audio setSlow calls sfx('slowIn') only if ctx+music; if ctx not init (title) no.

Starting audio: `audio.init()` on click. `startMusic()`.

End run:
```js
function endRun(victory) {
  app.state='gameover';
  const previousBest=app.best;
  const stats={...game.stats, score: Math.round(game.score), time: game.elapsed, borrowed: game.stolen};
  if (stats.score > previousBest) save
  app.best = Math.max(previousBest, stats.score)
  ui.showEnd({victory, stats, best: app.best, previousBest});
  audio.stopMusic();
  audio.setPaused(false);
  input clear
}
```
Need detect game.status 'dead'/'won' each frame when app.state==='playing'. After `game.update`, if `game.status==='dead'` endRun(false) else if 'won' endRun(true). `endRun` calls UI update with game stats. `game.status` remains dead/won; renderer draws frozen.

Victory sound already played in killBoss, stop music after overlay appears at 2.8s (music continues until then) — maybe stop music immediately on victory? endRun only when status won after timer; music plays during victory animation. Good.

Best storage:
```js
function loadBest(){ try{ const raw=localStorage.getItem('borrowed-seconds-best'); const n=Number(raw); return n>0?n:0}catch{return 0}}
saveBest.
```
Maybe store JSON with best score only; fine.

Restart:
- `startGame()` while app.state gameover. Need hide end overlay: ui.resetRun hides gameover, but game status resets. title hidden already. fine.
- On quit to title: app.state='title'; game.status='title'; clear arrays? Need reset title scene: `game.enemies=[]; game.bullets...; game.debt=[]; game.player.hp=...; game.status='title'`; ui.showTitle(); ui.setPlaying(false); audio.stopMusic(); audio.setPaused(false). Renderer draws title scene. Good. Create `goTitle()`.
- Game.reset to get a clean player? Game constructor reset then clear arrays; we can call `game.reset()` then clear and set status title, but reset fires banner/toast (UI can clear). Simpler: reuse: `game.status='title'; game.enemies=[]; game.bullets=[]; game.particles=[]; game.rings=[]; game.texts=[]; game.pickups=[]; game.debt=[]; game.player.hp=100; game.player.dead=false; game.stolen=0; game.score=0; game.boss=null; game.timeScale=1;` and `ui.showTitle()`.

UI title best update.

UI start/pause/end wiring:
- btn-play click → audio sfx ui, startGame.
- btn-again → startGame.
- btn-title → goTitle.
- btn-resume → togglePause.
- btn-quit → goTitle.
- btn-pause-mute → toggleMute.
- btn-audio → toggleMute.
- btn-pause → togglePause.
- btn-slow pointerdown/up.
- btn-dash pointerdown.
- Prevent buttons from stealing focus? It's fine.

Keyboard:
```js
window.addEventListener('keydown', e=>{
 const key=e.key.toLowerCase();
 if (['arrowup',...].includes(key)) e.preventDefault();
 if (key===' '){ e.preventDefault(); if(!e.repeat && app.state==='playing') dashQueued=true; }
 if (key==='shift') slowKey=true;
 if (key==='p'||key==='escape') { if(app.state==='playing'||app.state==='paused') togglePause(); }
 if (key==='m') toggleMute();
 if (key==='enter' && app.state==='title') startGame();
 // Prevent space from activating focused Play button after start? If title, pressing space on button triggers start; fine.
});
```
Shift keyup sets false. Note e.key 'Shift' lower 'shift'. Good.

`dashQueued` on Space while typing? No inputs.

Mouse:
```js
canvas.addEventListener('pointerdown', e => {
 if (e.pointerType === 'mouse') {
   mouse.x=e.clientX...
   if (e.button===0) { mouse.down=true; }
   if (e.button===2) mouse.right=true;
 } else {
   handleTouchStart(e);
 }
});
window.addEventListener('pointermove', ...);
window.addEventListener('pointerup', ...);
canvas.addEventListener('contextmenu', e=>e.preventDefault());
```
Pointer events on canvas only start touch sticks. Since canvas covers viewport behind HUD, touches on HUD panel (pointer-events none) reach canvas! HUD panels have pointer-events none; buttons auto. So dragging on HUD could start stick. That's acceptable for touch; but top-area touch shouldn't. Restrict touch start to y > h*0.45 and not near HUD. Good:
```js
if (e.clientY < h*0.42) return;
```
Zone left/right by x < w/2. Buttons are above y ~636 (on 844, y>0.42h=354, so button events are on DOM, not canvas; fine).
- Origin at touch; move stick.
- For move/aim stick, active if pointer id matches.
- On pointerdown on canvas for touch, use `e.preventDefault()`; setPointerCapture.
- Once captured, pointermove events go to canvas; window listener still sees.

Sticks object:
```js
sticks: {move:{active:false,pointerId:null,originX:0,originY:0,x:0,y:0,dx:0,dy:0}, aim:{...}}
```
On move update dx/dy = x-origin, clamp to max 46 for visual? Keep raw; game uses clamp /40.

TouchMove sets `moveX = clamp(dx/40,-1,1)`, similarly my; but analog magnitude; allow magnitude up to 1. Compute normalize if >1. Game normalizes anyway.

Mouse update: `mouse.x/y` on window pointermove for pointerType mouse; also hover. `handleMouseMove`.

Right mouse: `pointerdown` with button 2 sets right; context menu prevented. Mouse pointerup clears both based on button.

`window.blur` clears keys, mouse down/right, slow, sticks.

UI touch mode on resize:
```js
const touchMode = isTouchMode();
ui.setTouchMode(touchMode); app.touchMode = touchMode;
```
But if resize during play, setPlaying? `ui.update` uses touchMode; touch element shown only if playing. setTouchMode doesn't show. Fine.

When Play is clicked on mobile, UI's `setPlaying(true)` uses stored touchMode; ensure computed before. On initial load, set.

Initial:
- ui.showTitle(); ui.setBest(best); ui.setMuted(audio.muted); ui.setTouchMode(touchMode).
- game.status='title'; renderer loops.

Render loop:
```js
let last=performance.now();
function frame(now) {
 const dt=Math.min(0.05,(now-last)/1000); last=now;
 updateInput();
 if (app.state==='playing') {
   game.update(dt);
   if (game.status==='dead'){ endRun(false); }
   else if (game.status==='won'){ endRun(true); }
 } else if (app.state==='title') {
   // game.time? renderer titleT handles; no update
 }
 ui.update(game, app.state==='paused');
 renderer.render(game, dt, app);
 requestAnimationFrame(frame);
}
```
But while game.status==='dying' app.state stays playing; game.update handles. When dead, endRun.

At title, game.player may still hold old state if returning; `goTitle` resets.

Paused: no game update; renderer render still called with app.state 'paused'; draw screen effects? It draws enemies; slow overlay maybe. Fine. UI update paused.

App.input includes sticks. We need renderer drawSticks only when touchMode; app.touchMode.

`ui.update` should be called even during title? HUD hidden; it returns early. Fine.

Pause overlay focus and key handling: P/Esc toggles. Escape when gameover? Could go title? not necessary.

Prevent click through overlays: CSS overlay z-index. Play button works.

Resize: renderer.resize on window resize/orientation; maybe debounce. Call directly. On mobile, address bar changes height; use `visualViewport`? Use window inner. Fine.

Test hooks:
```js
window.__BORROWED = {
  get state(){return app.state}, game, audio, start:startGame, restart:startGame,
  spawnCollector(){game.spawnCollector()}, setWave(n){game.wave=n; game.waveT=0; if(n>=5){game.bossSpawnT=0.1; game.bossSpawned=false;}},
  damage(n=10){game.damagePlayer(n)}, win(){ if(game.boss){game.boss.hp=0; game.killBoss();} else {game.wave=5; game.spawnBoss(); game.boss.spawnT=0; game.boss.hp=0; game.killBoss();} },
  forceBoss(){...}, boon(){ add debt? }
};
```
Expose only if URLSearchParams has 'test'? Simpler always; harmless. But game uses `window.__BORROWED` for testing; fine. For spoilers? No.

To test corrosion/debt quickly: hook `borrow(n)` calls addDebt n times and increments stolen. We'll add.
`spawnCollector` direct.
`setDebt(fuse)` maybe.

Also test hit detection: can set enemy hp low etc.

Main sets `game.input` fields from input. Note game.reset sets input.fire=false etc but preserves object; main resets each frame.

`updateInput` while app.state!=='playing': set move 0, fire false, slow false, dash false. But touch time button could remain held across pause; reset.

Audio:
- On start click, `audio.init(); audio.startMusic();`
- `audio.setMuted` persists.
- Toggle mute updates ui; when unmuted while ctx exists resume. Audio.init on click.
- On pause, audio.setPaused(true). On resume false. On end, stopMusic; setPaused false.
- When goTitle, stopMusic.

`onSlowChange` set to `(active) => { audio.setSlow(active); }`; UI slowwash handled each frame. On die, game calls onSlowChange(false) → audio slowOut; music may be stopping later. Fine.

Score best: endRun compute `const stats={...game.stats, score: Math.round(game.score), time: game.elapsed, borrowed: game.stolen, wave: game.wave}`. game.stats.score may not be updated for victory until status won; use game.score directly.

Save highest score. New best check against previous. Update best before ui.showEnd but pass previousBest.

Title best display updates on goTitle and after end.

HUD end: ui.hideHud called in showEnd.

Potential issue: capture auto-start clicks Play then waits 1000ms. At 1s, first enemies spawn animation started at 0.75+; at 1s only first husk becomes active; good. HUD visible, banner may still be showing "WAVE 01" (2.4s animation), toast visible. Screenshot nice.

But the title fade-out takes 430ms while game starts; screenshot at 1s after click fully clear.

Audio init from click - fine.

The Play button's label has aria-label "Play"; capture clicks. Good.

Now write main.js.

