import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";

const require = createRequire("/home/runner/.local/share/omgithub-playwright/package.json");
const { chromium } = require("playwright");

mkdirSync("/home/runner/work/PlayGround/PlayGround/screenshots", { recursive: true });
const base = "http://127.0.0.1:3000";
const errors = [];
const results = [];

function check(name, condition, detail = "") {
  results.push({ name, ok: Boolean(condition), detail });
  console.log(`${condition ? "PASS" : "FAIL"} ${name}${detail ? ` — ${detail}` : ""}`);
}

async function record(page, label) {
  page.on("pageerror", (error) => errors.push(`${label} pageerror: ${error.message}`));
  page.on("console", (message) => {
    if (message.type() === "error") errors.push(`${label} console: ${message.text()}`);
  });
  page.on("response", (response) => {
    if (response.status() >= 400 && response.url().startsWith(base)) {
      errors.push(`${label} HTTP ${response.status()}: ${response.url()}`);
    }
  });
}

const browser = await chromium.launch({ headless: true });

// ---------------------------------------------------------------- desktop
const desktop = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const page = await desktop.newPage();
record(page, "desktop");
await page.goto(base, { waitUntil: "load" });
await page.waitForTimeout(700);
await page.screenshot({ path: "screenshots/test-title.png" });
check("title visible", await page.locator("#title").isVisible());
const playBox = await page.locator("#btn-play").boundingBox();
check("play button visible", Boolean(playBox && playBox.width > 40), JSON.stringify(playBox));

await page.locator("#btn-play").click();
await page.waitForTimeout(1200);
await page.screenshot({ path: "screenshots/test-start.png" });
let state = await page.evaluate(() => window.__BORROWED.app.state);
check("game starts", state === "playing", state);
const hudVisible = await page.locator("#hud").isVisible();
check("hud visible", hudVisible);
const enemyCount = await page.evaluate(() => window.__BORROWED.game.enemies.length);
check("initial enemies present", enemyCount >= 3, String(enemyCount));

// Aim assist the test with the renderer's transform and fire at nearest targets.
async function aimAndFire(ms) {
  await page.mouse.move(900, 450);
  await page.mouse.down();
  const until = Date.now() + ms;
  while (Date.now() < until) {
    const target = await page.evaluate(() => {
      const { game, renderer } = window.__BORROWED;
      let best = null;
      let bestD = Infinity;
      for (const enemy of game.enemies) {
        if (!enemy.alive || enemy.spawnT > 0) continue;
        const d = Math.hypot(enemy.x - game.player.x, enemy.y - game.player.y);
        if (d < bestD) {
          best = enemy;
          bestD = d;
        }
      }
      if (!best) return null;
      return {
        x: renderer.cx + best.x * renderer.scale,
        y: renderer.cy + best.y * renderer.scale,
      };
    });
    if (target) await page.mouse.move(target.x, target.y);
    await page.waitForTimeout(90);
  }
  await page.mouse.up();
}

await aimAndFire(3500);
const combat = await page.evaluate(() => ({
  kills: window.__BORROWED.game.stats.kills,
  score: window.__BORROWED.game.score,
  hp: window.__BORROWED.game.player.hp,
}));
check("combat kills enemies", combat.kills > 0, JSON.stringify(combat));
await page.screenshot({ path: "screenshots/test-combat.png" });

// Steal time and build debt.
await page.evaluate(() => {
  window.__BORROWED.game.player.invuln = 999;
  window.__BORROWED.game.player.hp = 100;
});
await page.keyboard.down("Shift");
await page.waitForTimeout(2600);
await page.screenshot({ path: "screenshots/test-slow.png" });
const debtState = await page.evaluate(() => ({
  stolen: window.__BORROWED.game.stolen,
  debt: window.__BORROWED.game.debt.length,
  timeScale: window.__BORROWED.game.timeScale,
}));
await page.keyboard.up("Shift");
check("time steal accrues debt", debtState.stolen >= 2 && debtState.debt >= 2, JSON.stringify(debtState));
check("slow motion active", debtState.timeScale < 0.6, String(debtState.timeScale));

await page.waitForTimeout(7800);
const collectorState = await page.evaluate(() => ({
  collectors: window.__BORROWED.game.enemies.filter((enemy) => enemy.type === "collector").length,
  debt: window.__BORROWED.game.debt.length,
  state: window.__BORROWED.app.state,
}));
check("collectors arrive from debt", collectorState.collectors > 0, JSON.stringify(collectorState));
await page.screenshot({ path: "screenshots/test-collectors.png" });

// Boss sequence.
await page.evaluate(() => {
  window.__BORROWED.game.player.invuln = 999;
  window.__BORROWED.boss();
});
await page.waitForTimeout(1500);
await page.screenshot({ path: "screenshots/test-boss.png" });
const bossState = await page.evaluate(() => ({
  boss: Boolean(window.__BORROWED.game.boss),
  bar: !document.getElementById("bossbar").classList.contains("is-hidden"),
}));
check("boss spawns with bar", bossState.boss && bossState.bar, JSON.stringify(bossState));

await page.evaluate(() => window.__BORROWED.win());
await page.waitForTimeout(3500);
const winState = await page.evaluate(() => ({
  state: window.__BORROWED.app.state,
  visible: !document.getElementById("gameover").classList.contains("is-hidden"),
  title: document.getElementById("end-title").textContent,
}));
check("victory overlay", winState.state === "gameover" && winState.visible, JSON.stringify(winState));
await page.screenshot({ path: "screenshots/test-victory.png" });

await page.locator("#btn-again").click();
await page.waitForTimeout(800);
const restartState = await page.evaluate(() => ({
  state: window.__BORROWED.app.state,
  hp: window.__BORROWED.game.player.hp,
  score: window.__BORROWED.game.score,
}));
check("restart resets run", restartState.state === "playing" && restartState.hp === 100 && restartState.score === 0, JSON.stringify(restartState));

// Death.
await page.evaluate(() => {
  window.__BORROWED.game.player.invuln = 0;
  window.__BORROWED.game.player.hp = 1;
  window.__BORROWED.game.damagePlayer(10);
});
await page.waitForTimeout(2400);
const deathState = await page.evaluate(() => ({
  state: window.__BORROWED.app.state,
  visible: !document.getElementById("gameover").classList.contains("is-hidden"),
  best: localStorage.getItem("borrowed-seconds-best"),
}));
check("death overlay", deathState.state === "gameover" && deathState.visible, JSON.stringify(deathState));
await page.screenshot({ path: "screenshots/test-death.png" });

await desktop.close();

// ---------------------------------------------------------------- mobile
const mobile = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
});
const mpage = await mobile.newPage();
record(mpage, "mobile");
await mpage.goto(base, { waitUntil: "load" });
await mpage.waitForTimeout(700);
await mpage.screenshot({ path: "screenshots/test-mobile-title.png" });
const mplay = await mpage.locator("#btn-play").boundingBox();
check("mobile play visible", Boolean(mplay && mplay.y + mplay.height < 844 && mplay.x >= 0), JSON.stringify(mplay));

await mpage.locator("#btn-play").click();
await mpage.waitForTimeout(1200);
await mpage.screenshot({ path: "screenshots/test-mobile-start.png" });
check("mobile touch controls", await mpage.locator("#touch").isVisible());
const mobileState = await mpage.evaluate(() => ({
  touchMode: window.__BORROWED.app.touchMode,
  state: window.__BORROWED.app.state,
  hud: !document.getElementById("hud").classList.contains("is-hidden"),
}));
check("mobile run active", mobileState.touchMode && mobileState.state === "playing" && mobileState.hud, JSON.stringify(mobileState));

// Synthetic twin-stick input.
await mpage.evaluate(() => {
  const canvas = document.getElementById("arena");
  const dispatch = (type, x, y, id) => {
    const target = type === "pointermove" ? window : canvas;
    target.dispatchEvent(
      new PointerEvent(type, {
        bubbles: true,
        cancelable: true,
        pointerId: id,
        pointerType: "touch",
        clientX: x,
        clientY: y,
        buttons: 1,
        isPrimary: true,
      })
    );
  };
  dispatch("pointerdown", 90, 740, 11);
  dispatch("pointermove", 125, 700, 11);
  dispatch("pointerdown", 300, 740, 12);
  dispatch("pointermove", 330, 700, 12);
});
await mpage.waitForTimeout(600);
const touchInput = await mpage.evaluate(() => ({
  move: window.__BORROWED.game.input.moveX,
  fire: window.__BORROWED.game.input.fire,
  aim: window.__BORROWED.game.input.aimAngle,
}));
check("touch sticks drive input", touchInput.fire && Math.hypot(touchInput.move, 0) >= 0, JSON.stringify(touchInput));
await mpage.evaluate(() => {
  const canvas = document.getElementById("arena");
  window.dispatchEvent(new PointerEvent("pointerup", { bubbles: true, pointerId: 11, pointerType: "touch" }));
  window.dispatchEvent(new PointerEvent("pointerup", { bubbles: true, pointerId: 12, pointerType: "touch" }));
});

// Hold slow via a synthetic pointer.
await mpage.evaluate(() => {
  document
    .getElementById("btn-slow")
    .dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, pointerId: 21, pointerType: "touch" }));
});
await mpage.waitForTimeout(1800);
const mobileSlow = await mpage.evaluate(() => ({
  slow: window.__BORROWED.game.input.slow,
  stolen: window.__BORROWED.game.stolen,
  debt: window.__BORROWED.game.debt.length,
}));
await mpage.screenshot({ path: "screenshots/test-mobile-debt.png" });
check("mobile slow button works", mobileSlow.slow && mobileSlow.stolen > 0.8, JSON.stringify(mobileSlow));
await mpage.evaluate(() => {
  document
    .getElementById("btn-slow")
    .dispatchEvent(new PointerEvent("pointerup", { bubbles: true, pointerId: 21, pointerType: "touch" }));
});

await mobile.close();
await browser.close();

const failed = results.filter((result) => !result.ok);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
if (errors.length) {
  console.log("\nBrowser errors:");
  for (const error of errors) console.log(error);
}
if (failed.length || errors.length) process.exitCode = 1;

