await page.goto("http://127.0.0.1:3000", { waitUntil: "load" });
await page.locator("#btn-play").click();
async function fps(label) {
  const result = await page.evaluate(
    () =>
      new Promise((resolve) => {
        let frames = 0;
        const start = performance.now();
        function tick(now) {
          frames += 1;
          if (now - start < 2000) requestAnimationFrame(tick);
          else resolve({ fps: frames / ((now - start) / 1000), elapsed: window.__BORROWED.game.elapsed, race: window.__BORROWED.game.time });
        }
        requestAnimationFrame(tick);
      })
  );
  console.log(label, result);
}
await page.waitForTimeout(500);
await fps("baseline");
await page.evaluate(() => {
  document.querySelectorAll(".grain, .vignette").forEach((el) => (el.style.display = "none"));
});
await fps("no overlays");
await page.evaluate(() => {
  document.querySelectorAll(".panel").forEach((el) => (el.style.backdropFilter = "none"));
});
await fps("no backdrop-filter");
await page.evaluate(() => {
  document.getElementById("hud").style.display = "none";
});
await fps("no hud");
await page.evaluate(() => {
  window.__BORROWED.renderer.drawBackdrop = function () {};
});
await fps("no backdrop canvas");
await page.evaluate(() => {
  window.__BORROWED.renderer.drawArena = function () {};
});
await fps("no arena");
await browser.close();

