207:       const angle = (i / 24) * TAU;
208:       ctx.beginPath();
209:       ctx.moveTo(Math.cos(angle) * R * 0.15, Math.sin(angle) * R * 0.15);
210:       ctx.lineTo(Math.cos(angle) * R * 0.955, Math.sin(angle) * R * 0.955);
211:       ctx.stroke();
212:     }
213: 
214:     for (let i = 0; i < 72; i += 1) {
215:       const angle = (i / 72) * TAU;
216:       const major = i % 6 === 0;
217:       const inner = R * (major ? 0.952 : 0.972);
218:       const outer = R * 0.99;
219:       ctx.strokeStyle = major ? "rgba(111,247,240,0.23)" : "rgba(111,247,240,0.06)";
220:       ctx.lineWidth = major ? 1.4 : 0.8;
221:       ctx.beginPath();
222:       ctx.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
223:       ctx.lineTo(Math.cos(angle) * outer, Math.sin(angle) * outer);
224:       ctx.stroke();
225:     }
226: 
227:     const numerals = ["XII", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI"];
228:     ctx.font = "500 12px 'SFMono-Regular', 'Liberation Mono', monospace";
229:     ctx.textAlign = "center";
230:     ctx.textBaseline = "middle";
231:     numerals.forEach((label, index) => {
232:       const angle = -Math.PI / 2 + (index / 12) * TAU;
233:       ctx.fillStyle = "rgba(160, 226, 228, 0.13)";
234:       ctx.fillText(label, Math.cos(angle) * (R - 24), Math.sin(angle) * (R - 24));
235:     });
236: 
237:     for (const crack of this.cracks) {
238:       ctx.strokeStyle = crack.color;
239:       ctx.lineWidth = crack.width;
240:       ctx.beginPath();
241:       crack.points.forEach((point, index) => {
242:         if (index === 0) ctx.moveTo(point[0], point[1]);
243:         else ctx.lineTo(point[0], point[1]);
244:       });
245:       ctx.stroke();
246:     }
247: 
248:     ctx.strokeStyle = "rgba(111,247,240,0.1)";
249:     ctx.lineWidth = 0.9;
250:     ctx.beginPath();
251:     ctx.arc(0, 0, 132, 0, TAU);
252:     ctx.stroke();
253:     ctx.setLineDash([3, 9]);
254:     ctx.strokeStyle = "rgba(255,79,109,0.14)";
255:     ctx.lineWidth = 1.2;
256:     ctx.beginPath();
257:     ctx.arc(0, 0, 152, 0, TAU * 0.72);
258:     ctx.stroke();
259:     ctx.setLineDash([]);
260:     ctx.strokeStyle = "rgba(111,247,240,0.13)";
261:     ctx.lineWidth = 1;
262:     ctx.beginPath();
263:     ctx.arc(0, 0, 66, 0, TAU);
264:     ctx.stroke();
265: 
266:     // Faint face marks near the centre.
267:     ctx.strokeStyle = "rgba(111,247,240,0.06)";
268:     ctx.lineWidth = 0.8;
269:     for (let i = 0; i < 12; i += 1) {
270:       const angle = (i / 12) * TAU;
271:       ctx.beginPath();
272:       ctx.moveTo(Math.cos(angle) * 140, Math.sin(angle) * 140);
273:       ctx.lineTo(Math.cos(angle) * 148, Math.sin(angle) * 148);
274:       ctx.stroke();
275:     }
276:     ctx.restore();
277: 
278:     this.arenaCache = { canvas, extent };
279:   }
280: 
281:   makeGradients() {
282:     const ctx = this.ctx;
283:     const arena = ctx.createRadialGradient(0, 0, 0, 0, 0, WORLD_RADIUS);
284:     arena.addColorStop(0, "rgba(17, 50, 62, 0.99)");
285:     arena.addColorStop(0.42, "rgba(10, 30, 43, 0.97)");
286:     arena.addColorStop(0.78, "rgba(5, 16, 28, 0.99)");
287:     arena.addColorStop(1, "rgba(2, 6, 13, 1)");
288:     this.arenaGradient = arena;
289: 
290:     const bg = ctx.createRadialGradient(
291:       this.w * 0.5,
292:       this.h * 0.45,
293:       0,
294:       this.w * 0.5,
295:       this.h * 0.5,
296:       Math.max(this.w, this.h) * 0.78
297:     );
298:     bg.addColorStop(0, "#0d2033");
299:     bg.addColorStop(0.46, "#06101d");
300:     bg.addColorStop(1, "#010409");
301:     this.bgGradient = bg;
302:   }
303: 
304:   seedScene() {
305:     const random = mulberry32(1337 + Math.round(this.w + this.h));
306:     this.stars = Array.from({ length: 110 }, () => ({
307:       x: random() * this.w,
308:       y: random() * this.h,
309:       size: 0.5 + random() * 1.5,
310:       alpha: 0.12 + random() * 0.55,
311:       phase: random() * TAU,
312:       drift: 2 + random() * 6,
313:       tint: random() < 0.18 ? "red" : random() < 0.4 ? "cyan" : "white",
314:     }));
315:     this.dust = Array.from({ length: 42 }, () => ({
316:       x: random() * this.w,
317:       y: random() * this.h,
318:       r: 0.6 + random() * 2.2,
319:       speed: 4 + random() * 12,
320:       phase: random() * TAU,
321:       alpha: 0.05 + random() * 0.16,
322:       tint: random() < 0.2 ? AMBER : CYAN,
323:     }));
324: 
325:     this.cracks = [];
326:     const crackRandom = mulberry32(91);
327:     for (let c = 0; c < 6; c += 1) {
328:       const angle = crackRandom() * TAU;
329:       const start = 60 + crackRandom() * 240;
330:       const points = [];
331:       let r = start;
332:       let a = angle;
333:       for (let i = 0; i < 6; i += 1) {
334:         points.push([Math.cos(a) * r, Math.sin(a) * r]);
335:         r += 24 + crackRandom() * 45;
336:         a += (crackRandom() - 0.5) * 0.32;
337:       }
338:       this.cracks.push({
339:         points,
340:         color: crackRandom() < 0.3 ? "rgba(255,79,109,0.16)" : "rgba(111,247,240,0.1)",
341:         width: 0.7 + crackRandom() * 1.3,
342:       });
343:     }
344:   }
345: 
346:   seedAmbient() {
347:     const random = mulberry32(77);
348:     this.ambient = Array.from({ length: 28 }, () => ({
349:       angle: random() * TAU,
350:       radius: 120 + random() * 260,
351:       speed: 0.05 + random() * 0.18,
352:       size: 0.8 + random() * 2.2,
353:       phase: random() * TAU,
354:       color: random() < 0.3 ? RED : random() < 0.5 ? AMBER : CYAN,
355:     }));
356:   }
357: 
358:   glowSprite(color) {
359:     if (this.glows.has(color)) return this.glows.get(color);
360:     const canvas = document.createElement("canvas");
361:     canvas.width = 64;
362:     canvas.height = 64;
363:     const ctx = canvas.getContext("2d");
364:     const gradient = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
365:     gradient.addColorStop(0, rgba(color, 0.95));
366:     gradient.addColorStop(0.18, rgba(color, 0.68));
367:     gradient.addColorStop(0.45, rgba(color, 0.22));
368:     gradient.addColorStop(1, rgba(color, 0));
369:     ctx.fillStyle = gradient;
370:     ctx.fillRect(0, 0, 64, 64);
371:     this.glows.set(color, canvas);
372:     return canvas;
373:   }
374: 
375:   drawGlow(x, y, size, color, alpha = 1) {
376:     const sprite = this.glowSprite(color);
377:     const ctx = this.ctx;
378:     const previous = ctx.globalAlpha;
379:     ctx.globalAlpha = previous * alpha;
380:     ctx.drawImage(sprite, x - size / 2, y - size / 2, size, size);
381:     ctx.globalAlpha = previous;
382:   }
383: 
384:   screenToWorld(x, y) {
385:     return {
386:       x: (x - this.cx) / this.scale,
387:       y: (y - this.cy) / this.scale,
388:     };
389:   }
390: 
391:   render(game, dt, app) {
392:     const ctx = this.ctx;
393:     const { w, h, dpr } = this;
394:     this.titleT += dt;
395:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
396:     ctx.clearRect(0, 0, w, h);
397: 
398:     this.drawBackdrop(game, dt);
399: 
400:     const shake = game.shake || 0;
401:     const sx = (Math.random() - 0.5) * shake;
402:     const sy = (Math.random() - 0.5) * shake;
403:     ctx.save();
404:     ctx.translate(this.cx + sx, this.cy + sy);
405:     ctx.scale(this.scale, this.scale);
406: 
407:     this.drawArena(game, app);
408:     this.drawRings(game);
409:     if (app.state === "title") {
410:       this.drawTitleScene(game, app);
411:     } else {
412:       this.drawPickups(game);
413:       this.drawEnemies(game);
414:       this.drawBoss(game);
415:       this.drawPlayer(game, app);
416:       this.drawBullets(game);
417:       this.drawParticles(game);
418:       this.drawTexts(game);
419:     }
420:     ctx.restore();
421: 
422:     this.drawScreenEffects(game, app);
423:     if (app.touchMode && (app.state === "playing" || app.state === "paused")) {
424:       this.drawSticks(app, game);
425:     }
426:   }
427: 
428:   drawBackdrop(game, dt) {
429:     const ctx = this.ctx;
430:     const { w, h } = this;
431:     const t = this.titleT;
432:     ctx.fillStyle = this.bgGradient || "#04060c";
433:     ctx.fillRect(0, 0, w, h);
434: 
435:     // Faint radial lift behind the arena.
436:     const glow = ctx.createRadialGradient(this.cx, this.cy, 0, this.cx, this.cy, this.radius * 1.35);
437:     const pressure = Math.min(1, (game.debt.length + (game.boss ? 2 : 0)) / 8);
438:     glow.addColorStop(0, `rgba(24, 92, 102, ${0.3 + pressure * 0.06})`);
439:     glow.addColorStop(0.5, "rgba(9, 40, 52, 0.16)");
440:     glow.addColorStop(1, "rgba(0, 0, 0, 0)");
441:     ctx.fillStyle = glow;
442:     ctx.fillRect(0, 0, w, h);
443: 
444:     // Distant nebulae.
445:     ctx.save();
446:     ctx.globalCompositeOperation = "lighter";
447:     const nebulaA = ctx.createRadialGradient(w * 0.16, h * 0.1, 0, w * 0.16, h * 0.1, Math.min(w, h) * 0.52);
448:     nebulaA.addColorStop(0, "rgba(28, 122, 132, 0.1)");
449:     nebulaA.addColorStop(1, "rgba(28, 122, 132, 0)");
450:     ctx.fillStyle = nebulaA;
451:     ctx.fillRect(0, 0, w, h);
452:     const nebulaB = ctx.createRadialGradient(w * 0.88, h * 0.92, 0, w * 0.88, h * 0.92, Math.min(w, h) * 0.5);
453:     nebulaB.addColorStop(0, "rgba(142, 32, 72, 0.09)");
454:     nebulaB.addColorStop(1, "rgba(142, 32, 72, 0)");
455:     ctx.fillStyle = nebulaB;
456:     ctx.fillRect(0, 0, w, h);
457:     ctx.restore();
458: 
459:     ctx.save();
460:     ctx.globalCompositeOperation = "lighter";
461:     for (const star of this.stars) {
462:       const sway = Math.sin(t * 0.16 + star.phase) * star.drift;
463:       const x = star.x + sway;
464:       const y = (star.y + t * star.drift * 0.45) % (h + 20) - 10;
465:       const alpha = star.alpha * (0.55 + 0.45 * Math.sin(t * 0.8 + star.phase));
466:       ctx.fillStyle =
467:         star.tint === "red"
468:           ? `rgba(255, 120, 140, ${alpha * 0.7})`
469:           : star.tint === "cyan"
470:             ? `rgba(111, 247, 240, ${alpha * 0.7})`
471:             : `rgba(220, 242, 255, ${alpha})`;
472:       ctx.beginPath();
473:       ctx.arc(x, y, star.size, 0, TAU);
474:       ctx.fill();
475:     }
476:     for (const mote of this.dust) {
477:       const x = (mote.x + t * mote.speed * 0.35 + Math.sin(t * 0.4 + mote.phase) * 12) % (w + 40) - 20;
478:       const y = (mote.y - t * mote.speed + h + 20) % (h + 40) - 20;
479:       ctx.fillStyle = rgba(mote.tint, mote.alpha);
480:       ctx.beginPath();
481:       ctx.arc(x, y, mote.r, 0, TAU);
482:       ctx.fill();
483:     }
484:     ctx.restore();
485: 
486:     // Slow drifting horizon lines on the far side of the arena.
487:     ctx.save();
488:     ctx.strokeStyle = "rgba(111, 247, 240, 0.028)";
489:     ctx.lineWidth = 1;
490:     for (let i = 0; i < 8; i += 1) {
491:       const y = ((t * 5 + i * 90) % (h + 200)) - 100;
492:       ctx.beginPath();
493:       ctx.moveTo(0, y);
494:       ctx.lineTo(w, y + Math.sin(i) * 30);
495:       ctx.stroke();
496:     }
497:     ctx.restore();
498:   }
499: 
500:   drawArena(game, app) {
501:     const ctx = this.ctx;
502:     const R = WORLD_RADIUS;
503:     const t = this.titleT;
504:     const pending = game.debt.length;
505:     const activeCollectors = game.enemies.reduce(
506:       (n, enemy) => n + (enemy.type === "collector" && enemy.alive ? 1 : 0),
507:       0
508:     );
509:     const pressure = Math.min(1, (pending * 0.55 + activeCollectors * 0.35 + (game.boss ? 0.6 : 0)) / 4);
510:     const pulse = 0.5 + 0.5 * Math.sin(t * 2.2);
511: 
512:     // Outer aura
513:     const aura = ctx.createRadialGradient(0, 0, R * 0.72, 0, 0, R * 1.12);
514:     aura.addColorStop(0, "rgba(111,247,240,0)");
515:     aura.addColorStop(0.74, `rgba(111,247,240,${0.03 + pressure * 0.02})`);
516:     aura.addColorStop(0.9, `rgba(255,79,109,${pressure * 0.09})`);
517:     aura.addColorStop(1, "rgba(0,0,0,0)");
518:     ctx.fillStyle = aura;
519:     ctx.beginPath();
520:     ctx.arc(0, 0, R * 1.13, 0, TAU);
521:     ctx.fill();
522: 
523:     // Floor
524:     ctx.fillStyle = this.arenaGradient;
525:     ctx.beginPath();
526:     ctx.arc(0, 0, R, 0, TAU);
527:     ctx.fill();
528: 
529:     ctx.save();
530:     ctx.beginPath();
531:     ctx.arc(0, 0, R, 0, TAU);
532:     ctx.clip();
533: 
534:     // Concentric clock rings.
535:     const rings = [0.14, 0.26, 0.38, 0.5, 0.62, 0.74, 0.85, 0.94];
536:     rings.forEach((fraction, index) => {
537:       ctx.strokeStyle = index === rings.length - 1
538:         ? `rgba(111,247,240,${0.16 + pressure * 0.12})`
539:         : `rgba(111,247,240,${0.035 + index * 0.006})`;
540:       ctx.lineWidth = index === rings.length - 1 ? 1.4 : 0.8;
541:       ctx.beginPath();
542:       ctx.arc(0, 0, R * fraction, 0, TAU);
543:       ctx.stroke();
544:     });
545: 
546:     // Radial spokes.
547:     ctx.strokeStyle = "rgba(111,247,240,0.035)";
548:     ctx.lineWidth = 0.7;
549:     for (let i = 0; i < 24; i += 1) {
550:       const angle = (i / 24) * TAU;
551:       ctx.beginPath();
552:       ctx.moveTo(Math.cos(angle) * R * 0.15, Math.sin(angle) * R * 0.15);
553:       ctx.lineTo(Math.cos(angle) * R * 0.955, Math.sin(angle) * R * 0.955);
554:       ctx.stroke();
555:     }
556: 
557:     // Edge ticks.
558:     for (let i = 0; i < 72; i += 1) {
559:       const angle = (i / 72) * TAU;
560:       const major = i % 6 === 0;
561:       const inner = R * (major ? 0.952 : 0.972);
562:       const outer = R * 0.99;
563:       ctx.strokeStyle = major ? `rgba(111,247,240,${0.16 + pressure * 0.2})` : "rgba(111,247,240,0.055)";
564:       ctx.lineWidth = major ? 1.4 : 0.8;
565:       ctx.beginPath();
566:       ctx.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
567:       ctx.lineTo(Math.cos(angle) * outer, Math.sin(angle) * outer);
568:       ctx.stroke();
569:     }
570: 
571:     // Clock numerals.
572:     const numerals = ["XII", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI"];
573:     ctx.font = "500 12px 'SFMono-Regular', 'Liberation Mono', monospace";
574:     ctx.textAlign = "center";
575:     ctx.textBaseline = "middle";
576:     numerals.forEach((label, index) => {
577:       const angle = -Math.PI / 2 + (index / 12) * TAU;
578:       ctx.fillStyle = `rgba(160, 226, 228, ${0.09 + pressure * 0.05})`;
579:       ctx.fillText(label, Math.cos(angle) * (R - 24), Math.sin(angle) * (R - 24));
580:     });
581: 
582:     // Cracks in the clock face.
583:     for (const crack of this.cracks) {
584:       ctx.strokeStyle = crack.color;
585:       ctx.lineWidth = crack.width;
586:       ctx.beginPath();
587:       crack.points.forEach((point, index) => {
588:         if (index === 0) ctx.moveTo(point[0], point[1]);
589:         else ctx.lineTo(point[0], point[1]);
590:       });
591:       ctx.stroke();
592:     }
593: 
594:     // Central sigil.
595:     ctx.strokeStyle = "rgba(111,247,240,0.09)";
596:     ctx.lineWidth = 0.9;
597:     ctx.beginPath();
598:     ctx.arc(0, 0, 132, 0, TAU);
599:     ctx.stroke();
600:     ctx.setLineDash([3, 9]);
601:     ctx.strokeStyle = `rgba(255,79,109,${0.1 + pressure * 0.12})`;
602:     ctx.lineWidth = 1.2;
603:     ctx.beginPath();
604:     ctx.arc(0, 0, 152, t * 0.04, t * 0.04 + TAU * 0.72);
605:     ctx.stroke();
606:     ctx.setLineDash([]);
607: 
608:     ctx.strokeStyle = "rgba(111,247,240,0.12)";
609:     ctx.lineWidth = 1;
610:     ctx.beginPath();
611:     ctx.arc(0, 0, 66, 0, TAU);
612:     ctx.stroke();
613: 
614:     // Clock hands — the minute hand spins while time is stolen.
615:     const stolenBonus = game.stolen ? game.stolen * 0.22 : 0;
616:     const hourAngle = -Math.PI / 2 + t * 0.035;
617:     const minuteAngle = -Math.PI / 2 + t * 0.22 + stolenBonus;
618:     ctx.strokeStyle = "rgba(180, 255, 250, 0.16)";
619:     ctx.lineWidth = 3;
620:     ctx.beginPath();
621:     ctx.moveTo(0, 0);
622:     ctx.lineTo(Math.cos(hourAngle) * 42, Math.sin(hourAngle) * 42);
623:     ctx.stroke();
624:     ctx.strokeStyle = `rgba(255,120,140,${0.18 + pressure * 0.2})`;
625:     ctx.lineWidth = 1.2;
626:     ctx.beginPath();
627:     ctx.moveTo(0, 0);
628:     ctx.lineTo(Math.cos(minuteAngle) * 72, Math.sin(minuteAngle) * 72);
629:     ctx.stroke();
630:     ctx.fillStyle = "rgba(111,247,240,0.3)";
631:     ctx.beginPath();
632:     ctx.arc(0, 0, 3, 0, TAU);
633:     ctx.fill();
634: 
635:     // Debt pressure crawls around the rim.
636:     if (pressure > 0.02) {
637:       ctx.globalCompositeOperation = "lighter";
638:       const arcLength = TAU * 0.12 + pressure * TAU * 0.52;
639:       const arcStart = t * 0.35;
640:       for (let i = 0; i < 3; i += 1) {
641:         ctx.strokeStyle = `rgba(255,79,109,${(0.12 + pressure * 0.22) * (0.6 + 0.4 * Math.sin(t * 1.6 + i))})`;
642:         ctx.lineWidth = 2 + i;
643:         ctx.beginPath();
644:         ctx.arc(0, 0, R - 7 - i * 5, arcStart + i * 0.5, arcStart + i * 0.5 + arcLength);
645:         ctx.stroke();
646:       }
647:       ctx.globalCompositeOperation = "source-over";
648:     }
649:     ctx.restore();
650: 
651:     // Outer boundary.
652:     ctx.strokeStyle = `rgba(111,247,240,${0.22 + pressure * 0.25})`;
653:     ctx.lineWidth = 1.6;
654:     ctx.beginPath();
655:     ctx.arc(0, 0, R, 0, TAU);
656:     ctx.stroke();
657:     ctx.strokeStyle = `rgba(255,79,109,${pressure * 0.18 * (0.6 + 0.4 * pulse)})`;
658:     ctx.lineWidth = 7;
659:     ctx.beginPath();
660:     ctx.arc(0, 0, R + 6, 0, TAU);
661:     ctx.stroke();
662: 
663:     // Giant echo rings beyond the arena wall.
664:     ctx.save();
665:     ctx.globalCompositeOperation = "lighter";
666:     for (let i = 0; i < 3; i += 1) {
667:       const ringRadius = R * (1.18 + i * 0.17);
668:       ctx.strokeStyle = `rgba(111,247,240,${0.035 - i * 0.008})`;
669:       ctx.lineWidth = 1;
670:       ctx.setLineDash([2, 16]);
671:       ctx.save();
672:       ctx.rotate(t * (i % 2 === 0 ? 0.018 : -0.014) + i);
673:       ctx.beginPath();
674:       ctx.arc(0, 0, ringRadius, 0, TAU);
675:       ctx.stroke();
676:       ctx.restore();
677:     }
678:     ctx.setLineDash([]);
679:     ctx.restore();
680: 
681:     // Rotating marker shards at the edge.
682:     ctx.save();
683:     ctx.rotate(t * 0.08);
684:     for (let i = 0; i < 4; i += 1) {
685:       ctx.rotate(TAU / 4);
686:       ctx.fillStyle = `rgba(255,79,109,${0.14 + pressure * 0.2})`;
687:       ctx.beginPath();
688:       ctx.moveTo(R + 1, -4);
689:       ctx.lineTo(R + 16, 0);
690:       ctx.lineTo(R + 1, 4);
691:       ctx.closePath();
692:       ctx.fill();
693:     }
694:     ctx.restore();
695: 
696:     if (game.boss && !game.boss.dead) {
697:       ctx.strokeStyle = `rgba(179,139,255,${0.12 + pulse * 0.1})`;
698:       ctx.lineWidth = 1;
699:       ctx.beginPath();
700:       ctx.arc(0, 0, R * 0.68, 0, TAU);
701:       ctx.stroke();
702:     }
703:   }
704: 
705:   drawTitleScene(game, app) {
706:     const ctx = this.ctx;
707:     const t = this.titleT;
708:     const p = game.player;
709: 
710:     // Ambient time dust.
711:     ctx.save();
712:     ctx.globalCompositeOperation = "lighter";
713:     for (const mote of this.ambient) {
714:       const angle = mote.angle + t * mote.speed * 0.12;
715:       const radius = mote.radius + Math.sin(t * 0.4 + mote.phase) * 16;
716:       const x = Math.cos(angle) * radius;
717:       const y = Math.sin(angle) * radius;
718:       this.drawGlow(x, y, mote.size * 9, mote.color, 0.16 + 0.1 * Math.sin(t + mote.phase));
719:     }
720:     ctx.restore();
