722:     // Future echoes pacing the rim.
723:     for (let i = 0; i < 3; i += 1) {
724:       const angle = t * 0.12 + (i / 3) * TAU;
725:       const x = Math.cos(angle) * 285;
726:       const y = Math.sin(angle) * 285;
727:       ctx.save();
728:       ctx.translate(x, y);
729:       ctx.rotate(angle + Math.PI / 2);
730:       ctx.globalAlpha = 0.13 + 0.04 * Math.sin(t * 0.8 + i);
731:       this.drawShipShape(23, RED);
732:       ctx.restore();
