735:     // The duelist waits at the centre.
736:     ctx.save();
737:     ctx.translate(p.x, p.y);
738:     ctx.rotate(-Math.PI / 2 + Math.sin(t * 0.5) * 0.06);
739:     const breathe = 1 + Math.sin(t * 1.2) * 0.03;
740:     ctx.scale(breathe, breathe);
741:     this.drawGlow(0, 0, 130, CYAN, 0.24);
742:     this.drawShipShape(28, CYAN, true);
