816:       // Motion smear.
817:       if (Math.hypot(enemy.vx, enemy.vy) > 20) {
818:         ctx.save();
819:         ctx.globalCompositeOperation = "lighter";
820:         this.drawGlow(enemy.x - enemy.vx * 0.04, enemy.y - enemy.vy * 0.04, enemy.r * 3.6, enemy.color, 0.14);
821:         ctx.restore();
