826:           break;
827:         case "gazer":
828:           this.drawGazer(enemy, game);
829:           break;
830:         case "brute":
831:           this.drawBrute(enemy);
832:           break;
833:         case "collector":
834:           this.drawCollector(enemy, game);
835:           break;
836:         default:
837:           break;
838:       }
839:       if (enemy.flash > 0) {
840:         ctx.save();
841:         ctx.globalCompositeOperation = "lighter";
842:         this.drawGlow(enemy.x, enemy.y, enemy.r * 4, "#ffffff", Math.min(0.8, enemy.flash * 6));
