1079:   drawEnemyTelegraph(enemy, game) {
1080:     const ctx = this.ctx;
1081:     const strength = clamp(enemy.telegraph / Math.max(0.001, enemy.telegraphMax), 0, 1);
1082:     const color =
1083:       enemy.type === "brute" ? VIOLET : enemy.type === "gazer" ? AMBER : enemy.type === "collector" ? RED : CYAN;
1084:     ctx.save();
1085:     ctx.globalCompositeOperation = "lighter";
1086:     this.drawGlow(enemy.x, enemy.y, (enemy.r + 30) * 2, color, 0.1 + strength * 0.18);
1087:     ctx.strokeStyle = rgba(color, 0.18 + strength * 0.5);
1088:     ctx.lineWidth = 1.2;
1089:     ctx.beginPath();
1090:     ctx.arc(enemy.x, enemy.y, enemy.r + 8 + strength * 8, 0, TAU);
