1092: 
1093:     if (enemy.type === "gazer" || enemy.type === "collector") {
1094:       const angle = Number.isFinite(enemy.lockAngle) ? enemy.lockAngle : 0;
1095:       ctx.strokeStyle = rgba(color, 0.2 + strength * 0.35);
1096:       ctx.lineWidth = 1;
1097:       ctx.setLineDash([3, 7]);
1098:       ctx.beginPath();
1099:       ctx.moveTo(enemy.x, enemy.y);
1100:       ctx.lineTo(enemy.x + Math.cos(angle) * 520, enemy.y + Math.sin(angle) * 520);
1101:       ctx.stroke();
1102:       ctx.setLineDash([]);
1103:     }
1104:     if (enemy.type === "brute") {
1105:       ctx.strokeStyle = rgba(VIOLET, 0.2 + strength * 0.4);
1106:       for (let i = 0; i < 12; i += 1) {
1107:         const angle = (i / 12) * TAU;
1108:         ctx.beginPath();
1109:         ctx.moveTo(enemy.x + Math.cos(angle) * (enemy.r + 6), enemy.y + Math.sin(angle) * (enemy.r + 6));
1110:         ctx.lineTo(enemy.x + Math.cos(angle) * (enemy.r + 22), enemy.y + Math.sin(angle) * (enemy.r + 22));
1111:         ctx.stroke();
1112:       }
1113:     }
1114:     ctx.restore();
1115:   }
