import { createRequire } from "node:module";
const require = createRequire("/home/runner/.local/share/omgithub-playwright/package.json");
const { chromium } = require("playwright");
const browser = await chromium.launch({ headless: true });
for (const [label, viewport, dsf, isMobile] of [
  ["mobile-dpr1", { width: 390, height: 844 }, 1, false],
  ["mobile-dpr2", { width: 390, height: 844 }, 2, true],
]) {
  const ctx = await browser.newContext({ viewport, deviceScaleFactor: dsf, isMobile, hasTouch: isMobile });
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.goto("http://127.0.0.1:3000", { waitUntil: "load" });
  await page.locator("#btn-play").click();
  await page.waitForTimeout(400);
  const result = await page.evaluate(
    () =>
      new Promise((resolve) => {
        let frames = 0;
        const start = performance.now();
        function tick(now) {
          frames += 1;
          if (now - start < 2000) requestAnimationFrame(tick);
          else resolve({ fps: +(frames / ((now - start) / 1000)).toFixed(1), elapsed: +window.__BORROWED.game.elapsed.toFixed(2) });
        }
        requestAnimationFrame(tick);
      })
  );
  console.log(label, result, "errors:", errors);
  await ctx.close();
}
await browser.close();

