import { createRequire } from "node:module";
const require = createRequire("/home/runner/.local/share/omgithub-playwright/package.json");
const { chromium } = require("playwright");
const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
await page.goto("http://127.0.0.1:3000", { waitUntil: "load" });
await page.waitForTimeout(500);
await page.locator("#btn-play").click();
await page.waitForTimeout(800);
const result = await page.evaluate(() => {
  const g = window.__BORROWED.game;
  let calls = 0;
  let sum = 0;
  const original = g.update.bind(g);
  g.update = (dt) => { calls += 1; sum += dt; original(dt); };
  const start = performance.now();
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({ calls, sum: +sum.toFixed(3), wall: +((performance.now() - start) / 1000).toFixed(3), elapsed: +g.elapsed.toFixed(3), time: +g.time.toFixed(3) });
    }, 2000);
  });
});
console.log(result);
await browser.close();

